INSERT INTO public."KnowledgeChunks" VALUES (2, 'CIT/Fit', 'Tố chất hợp CNTT: thích giải quyết vấn đề theo từng bước, tò mò cách hệ thống hoạt động, kiên nhẫn khi debug. Không cần “siêu giỏi Toán” nhưng cần logic cơ bản, tinh thần tự học và thói quen thử–sai. Người hợp CNTT thường có động lực khi thấy mình tạo ra sản phẩm chạy được. Ngoài ra, kỹ năng giao tiếp (mô tả vấn đề, làm việc nhóm) quan trọng vì dự án thật hiếm khi làm một mình.', 'CIT', '[-0.037705578,0.3928581,-3.3784275,-0.41730908,1.7021185,-0.76072603,1.2536432,0.12474657,-0.7676939,-0.4902772,-1.1430063,1.065928,0.7257945,0.4598003,-0.21591638,-0.14279373,-0.46346673,-0.12901625,-0.276753,1.0591387,-0.48161927,0.7397543,-1.6702887,-0.94304985,2.285371,-0.49166843,0.20071517,0.69922805,-0.33671346,0.29680386,0.9307506,-0.6595899,0.18483132,0.89474696,-1.8857014,-1.3280128,0.80399066,0.37478277,1.2670112,0.2509156,0.87017167,1.0984266,-0.07167764,-0.41382778,-0.502764,0.4196616,-0.23413302,0.52908766,0.84317136,-2.000735,-0.37955683,-0.6374262,0.3320922,-1.3228166,0.7475677,1.6339643,0.13313241,0.52666545,0.7995254,-0.06467436,1.2679675,0.66874164,-0.8703255,0.28491226,0.38887095,-0.8937267,0.59382814,0.9675859,0.23409575,-0.082478054,0.8620479,-0.0678623,0.59484273,1.1362281,-1.1583025,-0.16814594,-0.18816854,0.34654573,0.41503012,0.7988108,-0.5233499,-0.96732724,1.4277871,0.09639884,0.13137472,-0.32405764,-0.54168177,0.13142237,-1.0091586,0.97843623,0.45545334,-0.33690998,0.19484371,0.012295921,-1.2729393,0.5638427,-0.37790295,0.656685,0.087521456,-0.5224635,-0.25978315,-0.091624685,0.80098236,-1.3166572,0.02395522,0.8881521,0.0692412,0.62367684,-0.81927794,0.23822138,0.5699924,0.45135903,-0.8828243,-0.4511725,0.8724505,0.48048633,1.2916466,-1.0282419,-0.0041172314,-0.10918987,-0.8316869,-0.17910078,-0.27824634,1.3923296,-0.039161354,0.99083984,-0.9523794,-0.017067034,0.37417755,-1.2997394,-0.07029729,-0.51698005,-0.38776377,0.7313529,-0.18697348,0.28957888,-0.24831423,-0.81917447,-0.34561646,0.1798777