INSERT INTO public."KnowledgeChunks" VALUES (3, 'CIT/NotFit', 'Khó khăn thường gặp khi học CNTT: học lan man nhiều công nghệ, thiếu dự án thực hành nên mất phương hướng, dễ nản vì sửa lỗi lặp lại. CNTT có thể không phù hợp nếu bạn rất ghét ngồi máy tính lâu, không thích đọc tài liệu, hoặc không chịu được việc thử–sai. Nếu vẫn thích CNTT nhưng sợ áp lực, có thể chọn hướng “chậm mà chắc”: học nền tảng + làm project nhỏ; hoặc hướng giao thoa (UIUX, BA, QA) để phù hợp tính cách hơn.', 'CIT', '[-0.21126603,0.9145917,-3.2533174,0.3536434,0.61858,-0.68285453,0.14959654,-0.04765538,-0.7355255,-0.39129943,-0.6092086,0.8371725,1.4044122,0.6190119,0.7150674,-0.32008994,-0.4049276,0.30866507,-1.3339623,1.2124916,-1.2141867,-0.10410294,-0.611122,-1.4929231,1.6452346,0.26516032,0.35330406,0.3935148,-0.46612713,-0.76184577,1.5197701,-1.1394806,-0.5415638,0.91352475,-2.0039475,-1.2685573,1.6848134,0.23427992,0.6464262,0.42492032,-0.34421012,0.057572037,-0.93144846,0.0022291422,1.1498871,-0.10356801,-0.53978324,0.14654323,1.301882,-1.0795336,0.062220532,0.97962457,-0.27783683,-0.62286454,0.07039354,0.8357825,-0.027938986,-0.5233157,0.7352248,0.23802204,1.101795,1.0122114,-1.0006174,1.2104429,1.1525683,-0.95684737,0.84344965,0.39724594,-0.12139757,0.3126343,0.36907083,0.022152994,0.17172924,0.60974866,-0.6224486,0.42120492,0.40878752,0.1520706,0.32006916,1.2548534,0.2032049,-1.4138875,1.1336286,-0.080376446,0.16475348,-0.16171476,0.11000795,0.0403678,-1.9368705,0.81857234,0.9552428,0.89164674,-0.2818133,0.08924577,-1.5300983,0.82274544,-0.8468364,0.81736606,0.00064569793,0.29313242,-0.2166366,-0.22457826,0.08952236,-0.718256,-0.38990468,1.4833767,0.04887361,1.3440905,-0.8247856,0.81506884,-0.03932217,1.0995748,-0.71324855,0.08279714,0.4438545,-0.5668495,0.96720195,-0.5158275,1.178177,-0.055613726,-1.6338601,-0.6595201,-0.2461636,0.32536945,0.3610931,0.912584,-0.6439619,0.06813582,0.45384383,-1.6954232,0.033263095,0.26257548,-0.75702846,0.6481453,-0.46325046,-0.079917096,-1.56608,-0.9