INSERT INTO public."KnowledgeChunks" VALUES (4, 'CIT/Study', 'Kiến thức phổ biến trong CNTT: (1) lập trình cơ bản, (2) cấu trúc dữ liệu & giải thuật, (3) cơ sở dữ liệu (SQL), (4) hệ điều hành và mạng máy tính, (5) kỹ nghệ phần mềm (phân tích yêu cầu, thiết kế, kiểm thử, Git), (6) phát triển ứng dụng (web/mobile/backend). Tùy định hướng có thể học thêm AI/ML, an ninh mạng, cloud, hoặc UI/UX. Với người mới, ưu tiên lập trình + SQL + làm project để hiểu quy trình xây sản phẩm.', 'CIT', '[-0.14659908,0.5332382,-3.4355545,-0.753556,1.2532959,-1.3653444,-0.32597476,-1.3451152,-0.30861157,-0.53225505,-1.104952,0.51981366,0.41926304,0.17512034,-0.38856104,-0.40963927,-1.0970099,-0.49750456,0.2263668,1.1356065,-0.6169853,-1.0147743,-0.06504467,-1.2859167,-0.33258164,0.9339326,0.37246376,-0.15531556,-0.8733567,-0.28744885,1.0108583,-0.4452365,-0.919019,0.5275699,-1.4282262,-0.08926354,0.8028146,-0.44981685,-0.03736481,0.43907133,0.37656233,-0.8031519,-0.23325714,-0.8968841,0.4861091,-0.10711888,0.8713599,0.51448315,1.8266896,-2.0765638,-0.54720765,0.7836641,0.18028267,-1.0855476,0.016115231,0.4289182,-0.6850173,0.39300382,-1.1934216,0.43113598,0.7868384,2.0135024,-0.0672112,0.900586,1.3159697,-0.511484,-0.6996863,1.7361469,-0.13858677,-0.14027172,0.8782951,-0.18705516,-0.64657867,0.46533728,-0.54909086,-0.25298747,-0.035412535,-0.15072922,0.09099293,0.52398866,0.33823165,-0.8025884,1.1456612,0.28015286,1.1246951,-0.22940706,-0.75857794,-0.3653455,-2.1565518,1.4213871,0.28278393,0.14033744,-0.4320377,0.27885485,-1.0335482,0.35219362,0.33897686,0.8346765,-0.45818728,-0.2471695,-0.76992166,-0.30548567,-0.10041734,-0.3672346,0.2704937,0.77075607,-0.5157586,1.0386202,-0.06948088,0.18427067,-0.062033493,0.3155995,-0.40624192,0.47268093,0.91577256,-0.3508603,1.2815797,-0.7149018,0.49238074,0.93743014,-0.87681264,-0.37794948,0.061243016,0.37021837,0.9545305,-0.3334874,-0.41119114,0.1896228,0.008505033,-1.381598,0.3242126,-0.13406119,-0.9890286,0.26890337,-0.32563782,-0.07639005,-1.24