INSERT INTO public."KnowledgeChunks" VALUES (5, 'CIT/Skills', 'Kỹ năng quan trọng khi học/làm CNTT: chia nhỏ bài toán, tự học từ tài liệu, debug có hệ thống, dùng Git và làm việc theo quy trình dự án. Khi làm thật, bạn cần giao tiếp để hỏi đúng yêu cầu, báo lỗi rõ và phối hợp nhóm. Về kỹ thuật, tùy nhánh sẽ cần thêm database/API, nền tảng mạng, hoặc thống kê dữ liệu. Học hiệu quả nhất khi mục tiêu là “có sản phẩm chạy được” (portfolio), không chỉ học lý thuyết.', 'CIT', '[0.13070114,0.7850217,-3.7650363,-0.09449638,1.4611236,-0.559436,1.0480415,-0.46661016,-0.55690795,-0.58398205,-1.3336749,0.15233499,0.913993,-0.12219969,0.0920512,-0.25519878,-0.22433779,-0.5292787,-0.74371374,1.6928104,-0.83183736,-0.22584082,-0.8522785,-0.43351325,1.9165419,-0.15958133,0.11500303,0.22990626,0.35606924,0.32099372,0.33648893,-0.17677727,0.015211212,0.974553,-1.1617082,-0.70048064,0.6885901,0.8659573,0.56394136,-0.16249627,0.49714136,0.9151121,0.2262017,-0.8819265,-0.18792787,0.90155596,0.58754295,0.42955324,1.0377665,-1.4376229,-0.4503586,0.8658997,0.5848525,-0.40222445,1.5901567,1.1556541,0.2153621,0.69700235,0.23406047,-0.7016051,1.0563926,0.11810592,0.19885692,1.41363,1.4001935,-0.76978564,0.21878341,0.39825955,-0.1595755,-0.38776723,0.56389457,0.6658867,0.23952453,1.3351693,-0.86505103,-0.054021847,0.11907579,-0.6316299,-0.2623583,0.40150642,-0.5207705,-0.6071985,1.0357773,-0.23235612,0.758269,0.1489063,-0.2671932,0.49857655,-0.83419317,0.42386198,0.33837488,-0.0042941314,0.086411074,0.31708202,-1.0931365,1.0489901,-0.4359235,0.75080615,-0.114716806,-0.29580396,-0.13415712,0.6267596,0.8361795,-0.820779,0.26161227,1.0698811,-0.1333107,0.76790434,-0.87654346,0.7098295,0.26551262,0.8537413,-0.72713673,-0.24880311,0.73067176,0.31797758,1.4365135,-0.81686985,-0.05471281,0.024928123,-2.1879551,0.21399425,0.48312816,0.8345658,0.16670091,0.91619,-1.5050449,0.23587634,1.0528624,-1.2673312,-0.33014923,-0.30529034,-0.6024511,0.5867528,-0.20315956,0.29045764,-0.84747225,-0.9724346,-0.48954