INSERT INTO public."KnowledgeChunks" VALUES (6, 'CIT/Careers', 'CNTT có cơ hội nghề nghiệp rộng: phát triển phần mềm (web/mobile/backend), hệ thống thông tin (IS), dữ liệu (DA/DS/BI), AI/ML, an ninh mạng (CY), mạng máy tính (NET), vận hành hệ thống (DevOps/Cloud), QA/BA/UIUX. Lộ trình phổ biến: intern → junior → mid → senior, hoặc chuyển sang quản lý/ chuyên gia. Thu nhập và cơ hội phụ thuộc mạnh vào năng lực thực hành, dự án đã làm và khả năng học nhanh hơn là chỉ bằng cấp.', 'CIT', '[-0.9928777,-0.07353108,-3.8503695,0.05265798,1.3129371,-0.9163722,0.6878336,-0.554393,0.5376668,-0.6663841,-1.0155969,1.3216438,0.6222062,0.0012403559,0.33628082,-1.3357401,-0.2874587,-0.8893005,-0.6299381,0.4593465,-0.34302378,-0.6433751,-1.0945002,-0.94457597,1.1401358,0.6953829,0.06640909,0.15847492,-0.69865733,0.04976703,0.8087826,-0.2227421,-0.20552002,1.1135308,-1.3820171,0.053897794,0.34689197,-0.16450556,-0.12377207,0.18583585,0.8005492,-0.9319213,-0.18681838,-0.7092967,0.33467203,0.112931944,-0.09744588,0.045609057,2.013614,-1.5047861,-1.3968258,-0.090467244,0.3122288,-0.8341766,0.7833819,0.4176304,-0.41563275,0.74667245,-0.22888647,-0.14629103,1.4147719,1.6777616,-1.0271308,1.373156,1.4037762,-0.7758281,-0.6043554,1.5453161,0.06366542,-0.6677992,0.66315544,0.96195287,-0.3371364,1.4494393,-0.93136525,-0.5930657,-0.43098307,-1.1497817,0.0815371,0.10975659,0.18762387,-0.9047324,1.2327452,0.652304,0.13114212,-0.16521955,-0.29661983,-0.3001251,-1.4053875,1.8507994,0.27902815,1.0981662,-0.13020258,0.8211787,-2.1677577,0.3989971,0.0011332883,1.07187,-0.23074684,-1.024212,-0.31706837,-0.9596713,0.35449642,-0.52699125,0.3564276,1.1113262,0.4374652,0.39400873,-0.09163769,-0.20077078,0.12765129,1.217703,-0.77514505,0.15246928,1.2949625,0.090561084,0.36424997,-0.4825878,0.59302765,0.5347349,-1.0483341,-0.4964671,-0.3112572,0.803176,0.66970223,0.7469551,-0.50757426,0.09502526,-0.041171845,-1.1442171,0.1460977,0.042597394,-0.59276485,-0.13825157,0.29202637,0.87655807,-1.3189659,-1.6475139