INSERT INTO public."KnowledgeChunks" VALUES (7, 'CIT/Requirements', 'Về Toán: không bắt buộc giỏi Toán nâng cao để học CNTT, nhất là hướng làm sản phẩm/web; quan trọng hơn là logic. Nhưng nếu theo DS/AI hoặc thuật toán chuyên sâu, Toán (xác suất thống kê, đại số tuyến tính) sẽ quan trọng. Về tiếng Anh: vẫn học được khi yếu, nhưng tiếng Anh giúp đọc tài liệu và hiểu lỗi nhanh hơn. Chiến lược an toàn: học đều 15–20 phút/ngày và giữ từ khóa kỹ thuật bằng tiếng Anh.', 'CIT', '[0.07904241,1.0292622,-3.3479564,-0.8586752,1.7457856,-0.17267586,1.4143593,-1.1455662,-0.5835974,0.0996325,-0.822129,1.0966711,0.7960256,-0.24022618,0.63187635,-0.552106,-0.9189212,-0.25229034,0.06295877,1.692611,-0.99235123,0.010758838,-1.3450199,-1.3888601,2.1976318,-0.75296026,-0.44477537,-0.054961253,-0.6485753,1.1489302,0.4869084,-0.22295012,-0.2150052,0.19213438,-1.2701356,-1.4615589,0.9385461,0.17590822,1.2409441,0.52769893,1.3931787,1.2843065,0.07113943,-0.59098643,-0.15229166,0.09212526,-0.24598342,1.1292008,0.8709509,-1.7073821,-1.278456,-0.3743136,-0.18064576,-0.9261407,1.1119215,1.3204939,-0.25300887,-0.06320614,0.16981836,0.72040427,1.876296,0.6302813,0.38420975,1.0074327,1.6574384,-0.31750846,0.32378435,1.1916462,0.40668568,0.4771073,0.78930384,-0.54368013,0.37335235,0.1179384,-0.53386176,-0.34421024,-0.4365345,-0.17393187,0.5863114,0.41029984,-0.54388267,-1.213633,2.0517962,0.38143274,-0.43650597,-0.7780606,-0.0428193,0.4433683,-0.43885306,1.3848808,0.50111425,-0.6818752,0.20333113,-0.14765301,-1.1378332,-0.0044688038,-0.25425613,0.7533606,-0.3357961,-0.24956325,-0.42211097,-0.13022205,-0.10380695,-0.60079324,-0.46834219,1.959756,-0.08024601,1.053667,-0.7030133,0.30647343,0.009029621,0.6703034,-0.6371062,-0.52385837,0.6007326,-0.36868632,0.4638732,0.04389186,-0.1582035,0.13178743,-0.5676451,-0.012038132,0.243176,1.4634787,-0.15886766,1.0440919,-1.2054172,0.023217387,0.5613893,-1.3547044,1.2687929,0.022278234,-0.73775935,0.050959814,-0.23152262,0.7853449,-1.2312772,-0.9017666,0.83812