INSERT INTO public."KnowledgeChunks" VALUES (8, 'CIT/AskBack', ' Để tư vấn đúng nhánh trong CIT, cần biết: (1) bạn thích làm sản phẩm (app/web) hay thích dữ liệu và phân tích? (2) bạn có hứng thú với trí tuệ nhân tạo không? (3) bạn có quan tâm bảo mật hoặc mạng máy tính không? (4) bạn chịu được luyện tập trên máy tính 2–4 giờ/ngày không? (5) mức Toán và tiếng Anh hiện tại ra sao? (6) mục tiêu của bạn là có việc sớm hay muốn học sâu? Từ đó có thể gợi ý hướng SE, DS, AI, CY, NET, IS, UIUX, CS hoặc EMB.', 'CIT', '[-0.1999894,-0.206486,-3.7491093,-0.43566573,1.4711468,-1.146579,0.4339636,-1.1717422,0.3046608,-0.40066642,-1.4268026,0.23339318,0.98951405,0.5802172,0.111741945,-1.2406003,-0.44326282,-0.25191483,-0.5579847,1.0524151,-0.2902165,-0.54041034,-0.6767603,-1.736799,1.4719845,-0.083102696,-0.2216741,0.03081958,-0.51188976,-0.19939399,-0.079664014,-0.33536664,-1.3690276,0.8411455,-1.3574091,-0.6639688,0.22946581,0.023979826,0.47974467,0.56455326,1.3256893,-0.6305775,-0.32371888,0.3816248,1.0095838,0.2621064,0.6524369,1.6537461,2.2041261,-2.4239826,-0.3545807,-0.42181548,-0.1597393,-1.4670111,0.22646342,0.7458461,-0.10974081,-0.6076592,0.026347877,0.4047544,1.2372494,1.4250412,-1.1294456,0.9899684,1.7146419,-0.37127876,0.43149894,1.7452457,-0.23098275,-0.2557717,1.4399525,-0.28880036,-0.024908876,-0.24670434,-0.89481694,-1.2216706,-0.678835,-0.4218143,0.47907305,0.68764377,-0.07677735,-0.7632782,1.3522292,0.6152924,0.47918364,-0.39236823,-0.5828775,-0.038113613,-1.2502075,0.773849,0.15364888,0.13025586,0.07666303,0.45876798,-1.824236,0.6160189,-0.1568406,0.7273492,-0.41292083,-1.2512429,-1.1222531,-0.15525527,0.43102452,-0.71718216,0.4948993,0.6924888,-0.21810469,1.848,-0.80856204,-0.80541635,0.08350089,1.3838987,-0.26110893,-0.17553714,1.1862527,-0.6639382,1.5768324,-0.23091626,0.83296424,0.45684016,-0.9509552,-0.32542554,-0.36355224,1.0335009,0.5437073,0.20100497,-0.688076,0.64249897,-0.4539001,-1.2846344,0.36569646,-0.24328987,-0.6122625,0.37979206,-0.28501704,0.