INSERT INTO public."KnowledgeChunks" VALUES (9, 'SE/ Overview', 'Software Engineering (SE) là hướng tập trung vào quy trình tạo ra phần mềm “chạy được và bền vững”: từ phân tích yêu cầu, thiết kế, lập trình, kiểm thử đến triển khai và bảo trì. SE không chỉ là viết code nhanh, mà là viết code có cấu trúc, dễ đọc, dễ mở rộng và làm việc nhóm hiệu quả. Nếu bạn thích xây sản phẩm (web/app), thích thấy kết quả rõ ràng và muốn có lộ trình nghề nghiệp phổ biến (intern → junior → senior), SE là lựa chọn rất phù hợp trong nhóm ngành CIT.', 'SE', '[-1.3495314,-0.5810457,-3.6940935,-0.43055886,0.91277575,0.003695819,-0.22668806,-0.6527588,0.325609,0.02050315,-0.23811483,0.74913174,0.50053865,0.10095114,-0.009916819,-0.63013655,-0.07179648,-0.63079643,-1.048977,-0.17274179,-0.9957592,-0.25769767,0.085180804,-1.2655702,1.1314609,-0.16864806,-0.016178055,-0.30104935,-0.51965725,0.57553047,0.20327292,-0.18339524,-0.576947,-0.052922588,-0.6889022,-0.4004687,0.6463765,-0.34155467,0.38431284,-0.40248019,0.4032868,-0.14914311,0.108374275,-0.34205762,-0.17020887,0.22648305,0.17407428,0.26019362,1.8803709,-1.1183294,-0.76369315,0.14586197,0.05715223,-0.722795,1.5580932,0.65720475,-1.4814918,0.19537954,-0.07190153,0.3935563,1.4117573,1.4666291,-1.02013,0.8129571,1.8807129,-0.51852614,0.81281024,1.1463672,-0.07649593,0.07248349,0.5883472,-0.05174884,-0.40609542,1.0900981,-1.1172553,-0.33537295,-0.15175156,-1.0729294,0.5285084,0.7519289,-0.42561302,-1.3869951,1.0812039,0.8263197,-0.36830965,-0.5277744,-0.5173569,0.40301514,-1.2791688,1.8237555,0.41445172,0.51080346,-0.5729969,0.8312971,-1.2216158,0.6578943,0.594031,1.0651847,-0.6765496,-0.22491017,-0.83615035,-0.19809143,0.5674397,-1.1327876,0.21703598,0.64140147,0.13051814,0.60623497,-0.61240625,0.045500807,1.1500704,1.0707809,-0.78382564,0.24310191,1.5780226,0.019030606,1.4739738,-0.958203,0.029773774,0.25025526,-1.2897102,-0.2520148,-0.7036021,1.2040113,0.255767,0.90362126,-0.96968615,0.40692878,0.026364129,-0.742184,0.16019288,-0.16435