INSERT INTO public."KnowledgeChunks" VALUES (1, 'CIT/Overview', 'Tổng quan nhóm ngành CNTT :Công nghệ thông tin (CIT) là nhóm ngành tập trung vào việc thiết kế, xây dựng và vận hành các hệ thống phần mềm, ứng dụng, dữ liệu và hạ tầng công nghệ. Người học CNTT thường làm việc với máy tính, giải quyết bài toán bằng tư duy logic, và biến ý tưởng/thông tin thành sản phẩm số như website, app, hệ thống quản lý, hoặc các mô hình phân tích dữ liệu. CNTT có nhiều nhánh như Software Engineering, Data Science, AI, Cybersecurity, Networks, Information Systems, UI/UX và cả các hướng giao thoa với thiết kế. Vì vậy, nếu bạn chưa chắc mình hợp nhánh nào, bạn vẫn có thể bắt đầu từ nền tảng chung (tư duy lập trình, cấu trúc dữ liệu, cơ sở dữ liệu), sau đó chọn nhánh dựa trên sở thích và trải nghiệm project nhỏ.', 'CIT', '[-0.50370115,0.9321357,-3.7520883,-0.7644254,1.3413627,-0.9427939,0.91178113,-0.7013644,-0.124852285,-0.3028056,-1.1573892,1.253638,0.6070467,-0.75981635,-0.19608593,-0.48827887,-0.75175107,-0.3139218,-0.23479651,1.4262292,-0.21308018,0.6559955,-0.86501354,-2.0634987,0.69518715,-0.45332193,-0.7038551,0.4352916,0.3251107,-0.03520528,1.1204098,-1.0563287,-1.1401622,1.1355312,-1.6876569,-1.2010857,0.20487455,0.39050984,1.1698337,0.41567346,0.49511424,-0.003603812,-0.35575563,-0.68263644,-0.012539336,-0.26232842,0.007077247,1.2428687,1.0092819,-2.0628119,-0.35986942,-0.15840062,-0.4526266,-1.0636599,0.7049239,0.20829785,-0.39800566,0.12897435,0.34625798,1.0918325,0.9990417,1.7743859,-0.60859704,0.7660873,1.5970104,-0.3035108,0.47752655,0.856542,0.6601082,0.7498367,1.5185486,-0.039301604,0.10238032,0.5964557,-0.2573715,-0.6039177,-0.03426609,0.0040240493,-0.024478717,1.075438,-0.17285332,-1.806291,1.3612375,0.9656139,0.1727923,-1.2648036,-0.46885577,-0.14070971,-1.3691317,1.7181227,0.49658617,0.5007709,-0.005426387,0.467008,-1.6719706,0.8408839,-0.06400781,1.0157527,-0.17313217,-0.06445788,-1.0571079,-0.68868214,0.085777745,-0.21242301,-0.098085746,1.7660086,-0.26597625,0