INSERT INTO public."KnowledgeChunks" VALUES (12, 'SE/Requirements', 'SE cần tư duy logic và kỹ năng giải quyết vấn đề hơn là Toán cao cấp. Bạn không cần giỏi đại số tuyến tính hay xác suất như hướng AI/DS, nhưng cần nền Toán logic cơ bản để suy luận điều kiện, vòng lặp và cấu trúc dữ liệu. Tiếng Anh quan trọng ở mức đọc hiểu tài liệu, API docs và thông báo lỗi. Nếu bạn yếu tiếng Anh, vẫn học SE được, nhưng nên luyện dần bằng cách đọc error message, README và tài liệu ngắn mỗi ngày.', 'SE', '[-0.48922056,0.93666565,-3.1084986,-0.71564627,1.6806425,-0.76063824,1.1023238,-0.779581,-0.11147104,-0.04741854,-0.52216554,0.698521,1.7673727,0.41814956,0.06921792,-0.05577839,-0.66197133,-0.6502355,0.27738306,0.5112761,-1.0703526,0.76680416,-0.9572984,-1.9493972,2.118181,-0.474504,-0.26875123,1.4179802,-0.74496764,1.3033619,0.4487539,-0.20070472,0.38950604,-0.46469212,-1.3700643,-1.9089316,-0.70731705,0.43744773,0.74176097,1.008394,0.5601278,0.4952388,0.10445849,-0.18506306,-0.59392476,0.098010495,-0.20683424,1.4464667,1.2978573,-1.9575905,0.36090758,-1.0814006,0.22671385,-0.9045078,0.8502739,1.5749742,-0.31066936,-0.07861392,0.16591986,-0.0072649773,1.292827,1.251096,-0.2398925,0.23831905,0.47865206,-0.7557614,-0.03078231,0.36334342,0.6491007,0.25892758,1.2960917,-0.78532153,0.03411483,0.8929871,-0.20980564,-0.0058024116,-0.046891544,0.5375078,0.35724357,0.2639355,-1.0911005,-1.0961268,1.8065466,0.17746946,0.1687483,-0.7983554,-0.43102184,-0.39460748,-0.728586,1.7158393,-0.13872609,-0.23569258,0.050165206,0.06421915,-1.1991639,0.79152066,0.15874702,1.3928214,-0.32914338,0.31037378,-1.0911136,-0.9582552,0.17707458,-0.38622624,-0.08494909,1.8210511,-0.06507313,0.48883772,-1.2256119,-0.64145756,0.4080415,1.3505123,0.07457063,-0.5270497,1.4313687,-0.8940007,0.62333286,-0.22323675,-0.052440256,-0.20370625,-0.26531306,-0.8409685,-0.3172055,1.4844822,0.9502559,0.41869608,-0.5014658,-0.47827673,0.9420418,-1.1495894,0.1612549,0.04143673,-0.8870915,-0.0068465457,-0.5374781,-0.32315984,