INSERT INTO public."KnowledgeChunks" VALUES (21, 'UIUX/Foundations', 'UI/UX tập trung vào việc thiết kế trải nghiệm và giao diện giúp người dùng đạt mục tiêu một cách dễ hiểu, ít lỗi và nhất quán.
INSERT INTO public."KnowledgeChunks" VALUES (10, 'SE/Learn', 'Kiến thức cốt lõi của SE thường gồm: lập trình vững (1 ngôn ngữ chính), cấu trúc dữ liệu cơ bản, cơ sở dữ liệu (SQL), nguyên lý thiết kế phần mềm (tách lớp, module, clean code), kiến trúc ứng dụng (MVC, client-server), API (REST), kiểm thử (unit/integration), và quy trình làm việc (Git, code review, CI/CD cơ bản). Ngoài ra, hiểu về hệ điều hành/mạng ở mức nền giúp bạn debug và triển khai tốt hơn. Học SE hiệu quả nhất khi đi kèm dự án thực hành theo từng giai đoạn.', 'SE', '[-0.5533867,0.0053585544,-3.0372424,-0.9584943,2.1144662,-0.6734307,1.1389546,-0.026884926,-0.36569253,-1.4358624,-0.4668994,1.0901061,0.58403045,0.71543545,-0.66662544,-0.80765414,-0.30149955,-0.40429422,-1.0319028,0.61623114,0.2138073,-0.25262523,-0.45676073,-1.243085,1.8577334,0.92856205,0.5295667,0.7333697,-1.0603667,0.15637735,0.5029406,-0.46793562,0.1559733,-0.36216307,-1.5513179,-0.28247625,0.4017696,0.17938596,0.085337095,0.14378375,0.60776806,0.43747643,0.22800888,-1.1315411,0.2929836,0.33874524,0.68107533,-0.640749,1.0115746,-1.355292,0.11414822,-0.41717595,0.6664041,-0.5766995,0.972764,1.1418175,-0.681822,0.6541744,0.14221397,-0.1270291,1.0372273,0.9085978,-0.4482716,0.41837803,0.67325205,-0.8152721,-0.0016785711,0.5401566,0.30355754,0.2105174,0.76440334,0.43268037,0.2889703,0.8267646,-1.2106884,-0.14664008,-0.31183875,-0.5481553,0.51607764,0.31976438,0.049103618,-0.8580302,0.65695196,0.011480156,0.28889203,-0.9368138,-0.8027165,0.04149589,-1.733561,1.2021581,-0.17758018,-0.1869157,-0.54760903,0.32939255,-1.4487216,0.16785239,-0.22257763,0.542497,-0.08255071,-0.7382886,0.18581694,0.5393782,0.8552,-0.9036729,-0.027488945,1.4225837,-0.12333759,0.8926807,-0.85778886,0.02271351,0.6421539,0.45736435,-0.19884616,-0.11894507,1.1924227,-0.06532933,1.8957992,-1.1423075,-0.69850814,-0.18061347,-0.93761253,-0.7264836,-0.06785076,0.6512787,1.7781565,0.23087451,-0.96154106,0.6059501,0.20916097,-1.2866648,0.01188756,-0.2544274,-0.8962194,-