INSERT INTO public."KnowledgeChunks" VALUES (11, 'SE/Fit', 'SE phù hợp với người thích xây sản phẩm, thích tư duy hệ thống và có tính kỷ luật trong cách làm việc. Nếu bạn thích “làm ra thứ người khác dùng được” (website/app), thích cải tiến dần sản phẩm qua từng phiên bản và chịu được việc sửa lỗi, tối ưu, SE rất hợp. SE cũng phù hợp với người thích làm việc nhóm vì trong thực tế bạn sẽ thường phối hợp với designer, QA, BA, và các lập trình viên khác.', 'SE', '[-1.3571444,0.6890365,-3.748259,-0.969232,0.45825568,-1.197893,0.13907585,-0.7018408,0.7607432,-0.6555692,-0.5015951,0.34034765,1.5649538,-0.05078793,-1.0968535,0.010058138,-0.21820512,-0.835263,-0.5721901,0.7073881,-1.1339407,-0.8644672,-0.35856092,-1.1037731,1.0538828,-0.75207484,-0.1320362,0.023508744,-0.82727545,-0.3316329,-0.3835585,-0.39221787,-1.4011637,0.29649425,-0.13881752,-0.36293307,0.05657245,-0.3623362,0.32307103,0.05087743,0.80037206,-0.47841886,-0.5490125,-0.69533026,0.6395006,-0.3218506,-0.18381779,0.31260303,1.2425187,-1.608102,0.5712685,0.21243839,0.011664062,-1.1799942,0.4935165,0.6329494,-0.27566817,0.34653014,-0.5874299,0.47098824,0.774399,2.682304,-1.1655179,1.6920587,1.9388922,-1.0081726,0.6206971,1.5085946,0.43680283,-0.4537576,1.1631937,-0.4200562,-0.14471573,-0.092737034,-0.46928003,-0.40016446,-0.10667759,-0.125296,0.114645585,0.95138603,-0.66409457,-1.4558468,0.55622923,0.9180789,0.8962633,-0.3798222,-0.43300217,0.8656576,-1.701883,1.7262208,-0.045570478,0.1934277,0.20401932,-0.35674667,-0.93494767,0.96122915,0.19035465,1.2762827,-0.44042453,0.15392654,-0.9040316,-0.12518297,0.13044693,0.03668223,0.46849823,0.5336536,0.22424793,0.6192941,-1.0559835,-0.38310087,0.46277148,0.2394572,0.17379005,0.48151308,1.4191837,0.13751371,2.2814655,-0.8517949,0.62446934,0.17315581,-0.6023516,-0.6829761,-0.4844043,0.13673691,0.73848677,0.13413975,-0.45580676,0.20922026,-0.1368587,-1.1014546,-0.104584605,-0.12722994,-0.96057814,-0.2722838,0.2168986,0.04539583,-0.5110509,-0.6204558,0.30913827,0.24186