INSERT INTO public."KnowledgeChunks" VALUES (13, 'SE/Projects', 'Project/portfolio gợi ý cho SE: (1) CRUD web app có đăng nhập (JWT), phân quyền user/admin; (2) API backend + database (Postgres) với thiết kế bảng rõ ràng; (3) ứng dụng quản lý (task, lớp học, thư viện) có tìm kiếm/lọc/phân trang; (4) mini e-commerce (giỏ hàng, đơn hàng); (5) tích hợp 1 dịch vụ ngoài (email, payment sandbox). Mỗi project nên có README, hướng dẫn chạy, và link demo (nếu deploy) để tăng độ tin cậy khi xin thực tập.', 'SE', '[0.122278586,1.145258,-2.8970559,-0.151426,1.1156609,-0.5862443,1.680529,-0.917249,0.22926916,-0.8863403,-0.9605097,-0.0870687,1.2019402,0.16631405,-0.26106858,-0.20978433,-0.22573988,-1.06734,-0.5861806,1.0871437,0.40968546,-1.2007195,-0.75205576,-1.5682555,1.1788751,0.5559696,0.14128274,0.2249437,-0.1278302,0.62088317,0.2676401,-0.4033364,-1.0359485,1.0430496,-0.3524444,-0.08978507,0.4176274,0.37314355,-0.45632207,-0.5055017,-0.54121596,0.014242638,0.3676786,0.16122097,1.3369225,0.649745,1.1864572,0.66099226,2.142819,-1.4370016,-0.61605346,0.21812558,-0.043173768,-0.103652894,0.85131365,-0.15958364,-0.18334955,0.36759487,0.41837156,-0.08325847,1.2642919,1.5600708,0.04761207,2.0317883,1.0574647,-0.72551495,-0.073798895,0.45773682,-0.13355567,-0.36981013,0.87243474,0.4119199,-0.1568119,0.26792884,-0.5034578,-0.5449291,-0.059552282,-1.1162093,-1.0409431,-0.21972622,0.95519733,-0.9694886,0.4643316,0.307103,1.1934562,-0.63854945,-0.39319906,-0.162389,-1.7029542,0.72647834,0.4404307,0.6280615,-0.475321,0.68207437,-0.8027588,0.5200525,-0.6582672,0.22488794,-0.55379635,-1.0412453,-0.07356186,0.21875772,-0.15980534,-0.10238528,0.3002379,1.1099849,-0.38995343,0.07147699,-0.2502704,0.21080214,0.44455212,0.57474786,-1.0405147,-0.0142066125,0.8803303,-0.12534666,1.4994373,-0.21563941,0.22458127,0.48182872,-1.0480304,-0.2648783,0.79945487,-0.18817976,0.6435156,0.19940947,-0.6891344,-0.46837363,-0.5747594,-1.6076342,0.15767452,-0.17922577,-0.712729,-0.30617362,0.111141145,0.50772