INSERT INTO public."KnowledgeChunks" VALUES (14, 'SE/Jobs', 'Vị trí phổ biến của SE gồm: Backend Developer, Frontend Developer, Full-stack Developer, Mobile Developer, QA/Automation (giao thoa), và sau này có thể chuyển sang Tech Lead hoặc Software Architect. Ở giai đoạn đầu, nhà tuyển dụng thường quan tâm: nền tảng lập trình, tư duy giải quyết vấn đề, cách bạn tổ chức code, và dự án thực tế. Bạn có thể bắt đầu với intern/junior qua việc xây portfolio, luyện thuật toán cơ bản và luyện giao tiếp mô tả dự án rõ ràng.', 'SE', '[-0.46626446,1.289135,-3.670047,-0.22170989,0.939989,-1.142978,1.0122315,-0.6292972,-0.31373426,-0.6748178,-1.5666869,0.86624676,1.1722709,0.3297731,-0.0099227745,-0.5814156,0.10905977,-0.43701783,-0.62435657,0.42593879,-0.5924659,-0.7952046,-0.5564794,-0.9006449,1.632683,0.77809834,0.29165655,0.61794615,-0.2604583,-0.6634858,0.60272783,-0.027046887,-0.59808475,0.5909738,-1.015215,-0.0548446,0.3956102,-0.33340666,0.16817391,-0.39994067,-0.43013796,0.48242265,0.21489573,0.22876923,0.49268255,0.396491,0.118802406,0.40108803,1.3212075,-1.3822836,0.035729565,0.67706066,0.12760827,-0.62371594,1.2735896,0.5543895,-0.3964975,0.84941953,0.3941349,-0.031200724,0.9863185,0.7742296,-0.7643305,0.7883173,1.6352853,-0.85056716,-0.060042992,0.38147894,0.101836056,-0.08810507,0.89647454,0.37752646,0.21262686,0.45014802,-1.2062881,-0.088298544,0.27908096,-0.6975394,0.27670714,0.43935528,-0.040585574,-0.89037764,1.180983,1.099282,-0.28440034,-0.47159463,-0.04584328,0.41870084,-2.0423357,1.0924095,0.06776475,0.8523402,-0.80796117,0.6325837,-1.5389823,0.75760883,-0.6402984,1.1478716,-0.52031076,-0.294654,-0.34274822,0.04544303,0.7022136,-1.068867,0.27091864,1.0664384,0.18366459,0.24533902,-0.53190446,0.23164083,0.7589393,1.6605406,-0.69973797,-1.0955498,0.90934354,-0.090524934,1.0499543,-1.0442169,-0.37459517,0.14519893,-1.7123532,-0.25808313,0.039084617,1.1786848,0.70108926,0.640239,-0.12322197,0.85549283,0.12750264,-1.2972469,0.6475398,-0.55252546,-0.78694123,0.67