INSERT INTO public."KnowledgeChunks" VALUES (15, 'DS/Overview', 'Data Science (DS) tập trung vào việc biến dữ liệu thành thông tin hữu ích để hỗ trợ ra quyết định. DS thường kết hợp thu thập/làm sạch dữ liệu, phân tích, trực quan hóa, xây mô hình dự đoán và đánh giá kết quả. DS khác với SE ở chỗ: SE chủ yếu xây “hệ thống phần mềm”, còn DS xây “insight/mô hình” từ dữ liệu. Nếu bạn thích dữ liệu, thích phân tích và tò mò “vì sao” đằng sau con số, DS là hướng phù hợp trong CIT.', 'DS', '[-0.5808063,-0.37006465,-3.3261473,-0.8123954,0.39178228,-0.69301385,0.32767338,-0.32120094,0.21541704,0.239345,-0.5688765,1.520925,-0.4270826,-1.1316586,-0.16027173,-1.0867933,-0.34263846,-0.32360563,-0.8954415,1.3311784,-0.59005475,0.70348614,-0.25013402,-1.3251396,0.8279524,0.32317266,-0.64201003,-0.50184137,-0.0244,-1.0498521,1.5131637,-1.1597117,-0.9732803,0.9721603,-1.3587817,-1.3172936,0.6614529,0.13273622,1.5563154,0.40324086,0.80405104,-1.2096645,-0.18021576,-0.83461124,0.4829699,0.22686176,-0.42465535,1.2253926,0.76503706,-1.6082933,-0.45837572,-0.09660334,-0.12952928,-1.1646006,-0.09148175,-0.28723526,-0.4630481,-0.5961923,-0.004070313,0.46511003,0.853834,0.81780094,-1.8195502,-0.36325994,1.5391214,-0.49416965,0.81829774,1.4589788,0.70595956,0.2774143,1.4292909,0.3024167,0.15610988,0.22825013,-0.028766785,-0.755288,-0.16583529,-0.601816,0.49533343,0.9778784,-0.43762845,-1.9609586,1.7241808,1.1025027,0.13757612,-0.7233409,-0.28741175,0.46460462,-1.110304,1.9962544,0.2207459,0.87943083,0.16838641,0.5488685,-1.5211052,0.8307831,0.25754687,1.4531522,-0.42466113,-0.44318965,-1.2490392,-0.64070433,0.8105403,-0.6523228,-0.0057638376,1.0951631,0.23578376,1.4433248,-1.3250979,-0.37041405,0.8389315,0.71771216,-0.7877302,-0.9121096,1.2598191,0.29156515,0.98867303,-1.5883819,0.26080295,0.31911126,-0.6081988,-1.0139232,-0.53089994,1.1871727,0.0035711627,0.6147469,-0.34148186,0.79187775,0.43363762,-1.200989,-0.106830455,0.3762855,-0.6013052,-0.011363949,0.12722723,-0.006570226,-1.3741024,-