INSERT INTO public."KnowledgeChunks" VALUES (16, 'DS/Learn', 'Kiến thức cốt lõi của DS thường gồm: (1) thống kê cơ bản và tư duy xác suất, (2) xử lý và phân tích dữ liệu (pandas/SQL), (3) trực quan hóa dữ liệu (matplotlib/seaborn hoặc công cụ BI), (4) mô hình machine learning cơ bản (hồi quy, phân loại, clustering), (5) đánh giá mô hình (train/test, overfitting), và (6) kỹ năng trình bày kết quả (report/dashboard). DS thực tế dùng nhiều SQL và kỹ năng làm sạch dữ liệu, không chỉ “train model”.', 'DS', '[-0.6528424,1.4049472,-3.5207498,-1.1024786,1.8050786,-0.66690105,0.6825855,-1.3444413,-0.6635638,-0.33998245,-0.13865905,0.16476706,2.1075857,0.2871327,-0.74545413,-0.9480125,-0.8001074,-0.87858546,-0.45358136,0.66803664,-0.5975057,0.013796229,-0.22873782,-0.82831925,0.6374755,1.0545253,-0.5480389,-0.083731055,0.0010374167,0.765433,0.60944504,-0.7061333,-0.9491778,-1.0244671,-1.6895747,-0.4985953,0.74605846,0.76298445,0.12810402,0.30759713,0.29419568,0.26127872,0.33234346,-0.3838025,0.16374584,-0.4062326,0.6379717,0.02847585,1.4970536,-0.9552719,0.25193316,0.55828255,0.37790045,-1.2505281,0.7219082,1.1861744,-0.8939253,-0.17245261,0.5649596,-0.29283422,1.0381577,0.79546225,-1.5724691,1.0714364,0.65811837,-0.27169204,-0.28283948,0.45942822,-0.08357351,-0.8543213,0.98047304,-0.3141968,0.05061268,0.5320083,-0.7421728,0.049767032,-0.04099962,-0.47268203,0.21617514,0.632357,0.9270953,0.33619127,1.5088825,0.63544244,1.1872758,-0.3841506,-1.1547749,-0.63302505,-1.3655583,1.0069618,-0.056328293,-0.32387713,0.20444933,0.558616,-0.86908334,0.74989754,0.32170567,0.18248951,-0.7337734,-0.6161288,-0.40852472,0.0712679,-0.15329032,-0.89371616,0.1654289,0.90598315,-0.2831882,0.758036,-0.3421427,-0.48565215,-0.75374705,1.5048906,-0.8650017,-0.5014157,0.1259976,-0.75243497,0.91672885,-0.48084474,-0.36755988,0.5252418,0.59865797,-0.45375082,0.2115953,0.27888086,0.010798435,0.5770607,-0.44745442,0.54002625,-0.58114046,-0.74454945,0.20711184,-0.5827845,-0.92758286,0.40635824,0.8386761,1