INSERT INTO public."KnowledgeChunks" VALUES (17, 'DS/Fit', 'DS phù hợp với người kiên nhẫn, thích phân tích, cẩn thận với dữ liệu và có tư duy “đặt câu hỏi đúng”. Bạn sẽ làm việc nhiều với bảng số, biểu đồ, và các giả thuyết. Nếu bạn thích tìm quy luật, thích giải thích bằng dữ liệu và không ngại thử nhiều cách để cải thiện kết quả, DS hợp. DS cũng hợp với người có khả năng trình bày vì kết quả phân tích cần được giải thích rõ cho người khác hiểu và ra quyết định.', 'DS', '[-0.9608272,-0.012111656,-3.9581625,-0.51745677,0.99877584,-1.466853,0.47461239,-0.9794317,0.09782219,0.10039397,-0.6985831,0.9504395,0.29973644,-0.32662883,0.04752291,-0.92565924,0.051889732,-1.0174944,-1.0417731,1.2805429,-1.4600055,0.66776687,1.0979785,-0.81024987,1.0998884,-0.63822883,0.81796443,0.29985094,-0.42584974,0.38421053,0.15014033,0.1542914,0.18310456,-0.6049334,-0.5708739,-0.57885474,0.21110326,0.4453025,0.36580536,-0.16260272,0.6039837,0.10049357,0.6673888,-0.81443876,-0.4876436,0.60639817,-0.64356214,1.1239105,1.2812761,-1.4138594,0.65150815,0.70420665,0.88701886,-1.3447245,1.0114881,1.6234069,-0.47391948,-0.9208869,-0.2827668,0.36178207,0.42486143,1.3670822,-0.7957816,0.1846938,1.4894983,-0.9104213,0.34424442,0.8237359,0.3763352,-0.1517267,1.1582408,-0.43795457,0.15889572,0.9191376,-0.68377787,0.26565865,-0.060846258,-0.048906967,0.8555805,0.32625175,-1.1928883,-0.969727,1.8197036,1.0120552,0.10308165,-0.60711324,-0.07066738,0.103434995,-1.1635648,1.3675934,-0.0014707281,0.033794817,0.4372115,0.9771165,-1.0150776,0.24770567,-0.023671407,1.5845804,-0.056164682,-0.074813835,-0.9768295,-0.34949914,0.7463153,-0.7837134,0.8085523,0.74241906,-0.23044595,0.99692106,-0.9885202,-0.12389065,-0.09999349,1.5694557,0.2407441,0.0067620915,1.5915183,0.3413053,1.104252,-1.1188912,0.20091347,0.2566149,-0.1933377,-0.25552925,-0.7757637,0.33358005,0.42542717,-0.08760482,-0.51496106,0.6406813,0.510144,-0.7830792,-0.47160083,0.2742209,-0.70008045,-0.23587526,-0.44190514,-0.033810545,-0.078458354,-1.76