INSERT INTO public."KnowledgeChunks" VALUES (18, 'DS/Requirements', 'DS thường cần Toán nhiều hơn SE, đặc biệt là xác suất thống kê và một phần đại số tuyến tính (tùy mức độ). Bạn không cần giỏi ngay từ đầu, nhưng nên sẵn sàng học dần vì hiểu thống kê giúp bạn tránh kết luận sai từ dữ liệu. Tiếng Anh quan trọng do tài liệu và thuật ngữ chuyên môn nhiều. Nếu bạn yếu Toán, vẫn có thể bắt đầu từ mảng Data Analyst/BI (thiên về SQL + dashboard) rồi tiến dần lên DS/ML khi nền thống kê tốt hơn.', 'DS', '[-0.5777713,0.4583711,-3.9222274,0.7579518,1.2142637,-1.1382104,0.9592693,-0.7689098,0.3258984,-1.008481,0.3669976,0.15248257,0.67893887,0.7419037,0.47945848,-0.69554543,-0.6418877,-0.599447,-0.98547214,1.9531311,-1.0216002,0.36290914,-1.6252028,-0.9779775,1.6140013,-0.2726346,1.0141219,0.37986615,-0.10094174,0.6231139,0.27979147,-0.35312417,-0.597452,0.10097379,-0.955964,-0.82856697,0.52319956,0.9255198,0.51737773,0.025456479,0.8457929,-0.5527626,0.12515607,-0.8561374,-0.11801234,0.4763091,0.059180982,0.8168945,1.8701925,-1.3719703,-1.1870519,0.5944906,-0.01614933,-1.6944907,1.0792694,0.54681116,0.012648482,-0.08346964,-0.25169417,-0.21661071,0.7258493,0.46517622,0.44470057,0.17483287,1.5174733,-0.19573677,0.3493492,0.99549663,0.101440094,-0.559342,1.3929257,0.7506233,0.74552953,0.7309564,-0.0028094111,-0.04611465,-0.60175335,0.055593517,0.5165991,0.7867924,0.6992919,-1.0148362,1.3990802,0.34043443,1.243308,-0.28184327,0.458474,0.4974096,-1.134959,-0.19609024,0.19198325,-0.20318402,0.52894825,0.39955863,-1.5443877,0.6989241,-0.20050555,0.8675016,0.4323981,0.30466607,-0.058320075,-0.1585856,0.7714424,-0.9953204,0.6019532,1.0230478,-0.17867602,1.2004046,-0.61667526,-1.1952697,-0.06941641,1.66932,0.26543683,0.057562467,1.3999075,-0.031844545,1.1787537,-1.237185,-0.21598648,0.25303796,-0.085848525,-0.68141305,0.2229241,0.5920418,0.27637267,-0.5628949,-1.0604095,0.68153065,0.12444328,-1.0060418,-0.36427245,-0.04971749,-0.79096645,0.37842375,0.013367457,0.45109528,-0.5881968,-1.