INSERT INTO public."KnowledgeChunks" VALUES (19, 'DS/Projects', 'Project/portfolio gợi ý cho DS: (1) phân tích một dataset công khai (giá nhà, điểm thi, bán hàng) với quy trình làm sạch → phân tích → biểu đồ → kết luận; (2) dashboard BI (Power BI/Tableau hoặc dashboard web) trả lời 5–10 câu hỏi kinh doanh; (3) mô hình dự đoán đơn giản (spam detection, dự đoán giá) kèm đánh giá; (4) bài toán phân cụm khách hàng (clustering) và diễn giải kết quả. Quan trọng nhất là bạn trình bày pipeline rõ ràng và giải thích vì sao chọn cách làm đó.', 'DS', '[-0.22586666,0.8794829,-3.8085086,-0.2654821,1.5711713,-0.8336213,1.2598029,-0.5320608,-0.25341848,-0.50160396,-0.6485724,0.5730415,1.4727345,0.35925144,-0.0435824,-0.12151922,-0.7087462,-1.5694484,-1.0439527,0.93016917,-0.5195842,-0.5954191,-0.08187004,-1.4548378,1.1100143,1.0915225,0.86864305,-0.7470344,0.6266264,0.30248314,0.13586076,0.61383754,-1.1730503,-0.060197104,-0.8294615,-0.7542284,0.49689144,-0.026471034,-0.43413195,-0.58313763,0.055620465,0.21523964,1.4076424,-0.39062485,0.22414222,0.41888303,0.47839433,0.70188683,2.538897,-1.3289189,-0.713742,1.0542854,-0.23978844,-0.8206395,0.87668896,0.16443062,0.010486744,0.5514014,0.3179163,-0.8309272,1.3374329,1.2495766,-0.1704139,1.2256463,1.1041952,-0.76291364,-0.13544193,0.3075963,0.040885482,-0.445632,0.58436316,0.7885536,-0.31151003,0.74551004,-0.9924337,-0.05755876,-0.18219551,-1.1226157,-0.15121529,0.27052084,0.39351818,-0.4375037,0.8836034,0.31200382,1.5279624,-0.41690907,-0.9044173,-0.48430172,-1.0713267,0.2809696,0.20812424,0.15196127,-0.5193241,0.4970625,-0.81646067,1.6699809,-0.2550541,0.39521807,-1.1878011,-0.54888535,-0.6496203,0.29032588,0.62989706,-0.25637677,0.29960024,1.002872,-0.0003002186,0.4334001,0.093749516,-0.37572572,0.61464745,0.7141512,-0.8128058,-0.81209815,0.7564461,0.2926117,1.5879366,-0.6009288,-0.41460913,0.30991104,-0.7195824,-0.2721412,-0.03688478,0.7051767,0.75838643,-0.2335586,-0.9026676,0.04728107,-0.17788777,-1.1730978,0.101606674,-0.407806