INSERT INTO public."KnowledgeChunks" VALUES (20, 'DS/Jobs', 'Vị trí liên quan DS gồm: Data Analyst (thiên phân tích), BI Analyst (dashboard), Data Scientist (mô hình/ML), và có thể phát triển sang ML Engineer (thiên triển khai) nếu bạn kết hợp tốt với kỹ năng SE. Khi tuyển dụng, người ta thường xem: kỹ năng SQL, tư duy thống kê, khả năng xử lý dữ liệu bẩn, và cách bạn trình bày kết quả. Nếu bạn muốn bắt đầu dễ hơn, hướng Data Analyst/BI là bước đệm tốt trước khi đi sâu DS/ML.', 'DS', '[-0.5674168,0.5629927,-4.2261004,0.18681723,1.5007212,-1.4716672,0.92901284,-0.70300734,-0.3415052,-0.29538536,0.17755602,0.54568934,0.6487059,0.011866527,0.28755957,-1.3981727,-0.86298543,-0.33676848,-0.51725686,1.8811495,-1.3303654,0.8271098,-1.6078303,-2.0405982,1.7778195,-0.3419624,0.8339047,0.5642241,-0.67020726,0.7176096,0.66693,0.05736439,-0.21760996,0.39571312,-1.1636374,-1.2935555,-0.16023377,0.741989,0.8263139,0.52403563,0.89065874,-0.46857512,-0.14573221,-0.54507375,0.26593056,0.124611214,-0.20371987,1.2752309,1.0965003,-2.3302777,-0.82846975,0.51953614,0.6221137,-1.2709976,1.0536386,0.21636991,-0.05083238,-0.16877443,0.35248092,-0.22786945,0.68076664,-0.07215439,0.1252288,0.16764507,1.1068553,-0.5201393,-0.14500217,1.1245335,0.30117083,0.020018268,1.7132206,0.43201292,-0.056185644,0.55473655,-0.15221642,-0.25719914,-0.39222375,-0.63676,0.53087056,0.57229096,0.023762183,-0.858119,2.0325007,0.8652255,0.4868914,0.07326954,0.58382756,0.541882,-0.8511098,1.0378377,0.9873454,-0.14852506,-0.14807557,0.36503512,-1.6325612,0.65174097,-0.23797275,1.8004006,0.17410785,-0.03504977,0.022488952,-0.18036807,0.30227047,-0.52640814,0.27619517,1.1778823,-0.5905107,1.0066056,-0.3720639,-0.7930437,-0.12953117,0.92201895,0.38527796,-0.62974584,1.6100504,-0.42027834,1.3816714,-0.894916,0.1630772,0.044941463,-0.6326345,-0.673944,0.96227187,0.56241006,0.3011031,0.010809269,-0.87776136,0.52451533,0.42247444,-0.7392068,-0.4538691,0.31375924,-0.688718,-0.21635255,0.3747899,-0.036056586,-0.56380755,-1