INSERT INTO public."Levels" VALUES (4, 'Level 2', '2025-12-01 21:20:08.724+07', '2025-12-01 21:20:08.724+07');
INSERT INTO public."Majors" VALUES (1, 'EDU', 'Khoa học giáo dục và đào tạo giáo viên', 'Nhóm ngành Khoa học Giáo dục và Đào tạo giáo viên sư phạm bao gồm các ngành học liên quan đến lĩnh vực giáo dục và đào tạo giáo viên. Đây là những ngành học đào tạo giáo viên chất lượng, có kiến thức sâu về phương pháp dạy và quản lý lớp học.', '2025-12-15 15:40:01.601498+07', '2025-12-15 15:40:01.601498+07');
INSERT INTO public."Majors" VALUES (2, 'ART', 'Nghệ thuật', 'Nhóm ngành năng khiếu, nghệ thuật bao gồm các ngành học liên quan đến sự phát triển và khai thác các năng khiếu và tài năng trong lĩnh vực nghệ thuật. Đây là những ngành học nhằm chuẩn bị và phát triển các kỹ năng nghệ thuật và tạo điều kiện cho sinh viên thể hiện và phát triển sự sáng tạo của mình.', '2025-12-15 15:40:01.601498+07', '2025-12-15 15:40:01.601498+07');
INSERT INTO public."Majors" VALUES (3, 'HUM', 'Nhân văn', 'Nhóm ngành Khoa học Nhân văn bao gồm các ngành học liên quan đến lĩnh vực xã hội, văn hóa, lịch sử và con người. Đây là những ngành học nhằm khám phá và hiểu sâu về các khía cạnh nhân văn của xã hội và cuộc sống.', '2025-12-15 15:40:01.601498+07', '2025-12-15 15:40:01.601498+07');
INSERT INTO public."Majors" VALUES (4, 'SOC', 'Khoa học xã hội và hành vi', 'Đây là nhóm ngành bao gồm các ngành học liên quan đến nghiên cứu và hiểu biết về xã hội, hành vi con người và các quá trình tâm lý. Đây là những ngành học nhằm khám phá và giải thích các khía cạnh xã hội, tâm lý và hành vi của con người.', '2025-12-15 15:40:01.601498+07', '2025-12-15 15:40:01.601498+07');
INSERT INTO public."Majors" VALUES (5, 'JOU', 'Báo chí và thông tin', 'Nhóm ngành báo chí, thông tin và truyền thông bao gồm các ngành học liên quan đến thu thập, xử lý và truyền đạt thông tin đến công chúng. Đây là những ngành học nhằm chuẩn bị và phát triển các kỹ năng liên quan đến việc làm trong lĩnh vực truyền thông và truyền thông đại chúng.', '2025-12-15 15:40:01.601498+07', '2025-12-15 15:40:01.601498+07');
INSERT INTO public."Majors" VALUES (6, 'BUS', 'Kinh doanh và quản lý', 'Nhóm ngành Kinh doanh và quản lý bao gồm các ngành học liên quan đến quản lý tổ chức và hoạt động kinh doanh. Đây là những ngành học nhằm chuẩn bị và phát triển các kỹ năng quản lý, lãnh đạo và kinh doanh trong các tổ chức và doanh nghiệp.', '2025-12-15 15:40:01.601498+07', '2025-12-15 15:40:01.601498+07');
INSERT INTO public."Majors" VALUES (7, 'LAW', 'Pháp luật', 'Nhóm ngành Pháp luật bao gồm các ngành học liên quan đến hệ thống pháp luật, luật pháp và quyền lợi trong xã hội. Đây là những ngành học nhằm chuẩn bị và phát triển các kiến thức và kỹ năng liên quan đến lĩnh vực pháp luật và hệ thống công lý.', '2025-12-15 15:40:01.601498+07', '2025-12-15 15:40:01.601498+07');
INSERT INTO public."Majors" VALUES (8, 'LIF', 'Khoa học sự sống', 'Nhóm ngành khoa học sự sống bao gồm các ngành học liên quan đến lĩnh vực sinh học, y học và nghiên cứu về sự sống. Đây là những ngành học nhằm chuẩn bị và phát triển kiến thức và kỹ năng liên quan đến các quá trình sinh học, cấu trúc và chức năng của hệ thống sống.', '2025-12-15 15:40:01.601498+07', '2025-12-15 15:40:01.601498+07');
INSERT INTO public."Majors" VALUES (9, 'SCI', 'Khoa học tự nhiên', 'Nhóm ngành khoa học tự nhiên bao gồm các ngành học liên quan đến các lĩnh vực khoa học cơ bản như vật lý, hóa học, toán học, thiên văn học và các ngành khoa học tự nhiên khác. Nhóm ngành này tập trung vào nghiên cứu và hiểu về các quy luật tự nhiên, các quá trình và hiện tượng trong vũ trụ và tự nhiên xung quanh chúng ta.', '2025-12-15 15:40:01.601498+07', '2025-12-15 15:40:01.601498+07');
INSERT INTO public."Majors" VALUES (10, 'MAT', 'Toán và thống kê', 'Nhóm ngành Toán và Thống kê bao gồm các ngành học liên quan đến lý thuyết và ứng dụng của toán học và thống kê. Đây là những ngành học nhằm chuẩn bị và phát triển kiến thức và kỹ năng trong lĩnh vực tính toán, mô hình hóa và phân tích dữ liệu.', '2025-12-15 15:40:01.601498+07', '2025-12-15 15:40:01.601498+07');
INSERT INTO public."Majors" VALUES (11, 'CIT', 'Máy tính và công nghệ thông tin', 'Nhóm ngành Máy tính và Công nghệ thông tin bao gồm các ngành học liên quan đến lĩnh vực máy tính, phần mềm, mạng và công nghệ thông tin. Đây là những ngành học nhằm chuẩn bị và phát triển kiến thức và kỹ năng liên quan đến việc thiết kế, phát triển và quản lý các hệ thống, ứng dụng công nghệ thông tin.', '2025-12-15 15:40:01.601498+07', '2025-12-15 15:40:01.601498+07');
INSERT INTO public."Majors" VALUES (12, 'TEC', 'Công nghệ kỹ thuật', 'Nhóm ngành Công nghệ kỹ thuật bao gồm các ngành học liên quan đến việc áp dụng kiến thức kỹ thuật và kỹ năng thực hành để thiết kế, xây dựng, vận hành và bảo trì các hệ thống công nghiệp và cơ sở hạ tầng. Đây là những ngành học nhằm chuẩn bị và phát triển kiến thức và kỹ năng trong lĩnh vực kỹ thuật và công nghệ.', '2025-12-15 15:40:01.601498+07', '2025-12-15 15:40:01.601498+07');
INSERT INTO public."Majors" VALUES (13, 'ENG', 'Kỹ thuật', 'Nhóm ngành Kỹ thuật bao gồm các ngành học tập trung vào việc áp dụng kiến thức và kỹ năng kỹ thuật để giải quyết các vấn đề trong các lĩnh vực công nghiệp, xây dựng, công trình, công nghệ và hệ thống.', '2025-12-15 15:40:01.601498+07', '2025-12-15 15:40:01.601498+07');
INSERT INTO public."Majors" VALUES (14, 'MAN', 'Sản xuất và chế biến', 'Nhóm ngành sản xuất, chế biến bao gồm các ngành học liên quan đến quá trình chế biến, sản xuất và quản lý trong lĩnh vực công nghiệp và sản xuất hàng hóa. Đây là những ngành học đào tạo kiến thức và kỹ năng liên quan đến quy trình sản xuất, quản lý sản xuất, chế biến vật liệu và quản lý chất lượng.', '2025-12-15 15:40:01.601498+07', '2025-12-15 15:40:01.601498+07');
INSERT INTO public."Majors" VALUES (15, 'ARC', 'Kiến trúc và xây dựng', 'Nhóm ngành Kiến trúc và Xây dựng bao gồm các ngành học liên quan đến thiết kế, xây dựng, quản lý và bảo tồn các công trình kiến trúc và hạ tầng. Đây là những ngành học đào tạo kiến thức và kỹ năng liên quan đến quá trình thiết kế, xây dựng và quản lý các công trình kiến trúc.', '2025-12-15 15:40:01.601498+07', '2025-12-15 15:40:01.601498+07');
INSERT INTO public."Majors" VALUES (17, 'VET', 'Thú y', 'Nhóm ngành Thú y bao gồm các ngành học liên quan đến chăm sóc, điều trị và bảo vệ sức khỏe của động vật, đặc biệt là động vật trong lĩnh vực nông nghiệp. Đây là những ngành học đào tạo kiến thức, kỹ năng liên quan đến y học thú y và quản lý sức khỏe động vật.', '2025-12-15 15:40:01.601498+07', '2025-12-15 15:40:01.601498+07');
INSERT INTO public."Majors" VALUES (18, 'HEA', 'Sức khỏe', 'Nhóm ngành Chăm sóc sức khỏe bao gồm các ngành học liên quan đến chăm sóc, điều trị và quản lý sức khỏe con người. Đây là những ngành học đào tạo kiến thức và kỹ năng liên quan đến nghiên cứu, chẩn đoán, điều trị và quản lý sức khỏe con người.', '2025-12-15 15:40:01.601498+07', '2025-12-15 15:40:01.601498+07');
INSERT INTO public."Majors" VALUES (22, 'ENV', 'Môi trường và bảo vệ môi trường', 'Nhóm ngành Môi trường và bảo vệ môi trường bao gồm các ngành học liên quan đến nghiên cứu, quản lý và bảo vệ tài nguyên tự nhiên và môi trường. Đây là những ngành học đào tạo kiến thức và kỹ năng liên quan đến bảo vệ và tái tạo môi trường, quản lý chất thải, nghiên cứu biến đổi khí hậu và phát triển bền vững.', '2025-12-15 15:40:01.601498+07', '2025-12-15 15:40:01.601498+07');
INSERT INTO public."Majors" VALUES (16, 'AGR', 'Nông, lâm nghiệp và thủy sản', 'Nhóm ngành nông, lâm nghiệp, thủy sản bao gồm các ngành học liên quan đến sản xuất, quản lý và phát triển các nguồn tài nguyên trong lĩnh vực nông nghiệp, lâm nghiệp và thủy sản. Đây là những ngành học đào tạo kiến thức và kỹ năng liên quan đến quá trình sản xuất, quản lý và bảo vệ các nguồn tài nguyên sinh vật và môi trường.', '2025-12-15 15:40:01.601498+07', '2025-12-15 15:40:01.601498+07');
INSERT INTO public."Majors" VALUES (19, 'WEL', 'Dịch vụ xã hội', 'Nhóm ngành Dịch vụ xã hội bao gồm các ngành học liên quan đến cung cấp và quản lý các dịch vụ hỗ trợ xã hội cho các cá nhân, gia đình và cộng đồng. Đây là những ngành đào tạo kiến thức và kỹ năng liên quan đến công tác xã hội, tư vấn, giáo dục và quản lý dịch vụ xã hội.', '2025-12-15 15:40:01.601498+07', '2025-12-15 15:40:01.601498+07');
INSERT INTO public."Majors" VALUES (20, 'TOU', 'Du lịch, khách sạn, thể thao và dịch vụ cá nhân', 'Nhóm ngành Du lịch, khách sạn, thể thao và dịch vụ cá nhân bao gồm các ngành học liên quan đến quản lý, phát triển và cung cấp các dịch vụ liên quan đến du lịch, khách sạn, thể thao và các dịch vụ cá nhân khác. Đây là những ngành học đào tạo kiến thức và kỹ năng liên quan đến quản lý, truyền thông, sáng tạo và tạo trải nghiệm cho khách hàng.', '2025-12-15 15:40:01.601498+07', '2025-12-15 15:40:01.601498+07');
INSERT INTO public."Majors" VALUES (21, 'TRA', 'Dịch vụ vận tải', 'Nhóm ngành Dịch vụ vận tải bao gồm các ngành học liên quan đến quản lý, điều hành và cung cấp các dịch vụ vận chuyển và giao thông. Đây là những ngành học đào tạo kiến thức và kỹ năng liên quan đến quản lý hệ thống vận tải, kỹ thuật phương tiện và các dịch vụ liên quan.', '2025-12-15 15:40:01.601498+07', '2025-12-15 15:40:01.601498+07');
INSERT INTO public."Majors" VALUES (23, 'SEC', 'An ninh, Quốc phòng', 'Nhóm các ngành học thuộc lĩnh vực an ninh, trật tự xã hội và quốc phòng được đào tạo tại các trường Công an nhân dân thuộc Bộ Công an và các trường Quân sự thuộc Bộ Quốc phòng.', '2025-12-15 15:40:01.601498+07', '2025-12-15 15:40:01.601498+07');
