INSERT INTO public."Submissions" VALUES (14, 3, 'CIT', 'Máy tính và công nghệ thông tin', NULL, NULL, 0.8661, '{"weights": {"C1": 0.25, "C2": 0.3, "C3": 0.2, "C4": 0.15, "C5": 0.1}, "criteria": [{"key": "C1", "label": "Academic Strength", "description": "Đánh giá môn học, tư duy học tập, khả năng học thuật"}, {"key": "C2", "label": "Interest", "description": "Điều bạn thích, hứng thú tự nhiên khi không bị áp lực"}, {"key": "C3", "label": "Skill", "description": "Bạn làm được gì tốt, thiên về thao tác – thực hành – kỹ thuật"}, {"key": "C4", "label": "Work Environment", "description": "Bạn phù hợp làm việc ở đâu – trong bối cảnh nào"}, {"key": "C5", "label": "Social Value", "description": "Bạn muốn đóng góp điều gì cho xã hội"}], "allScores": [{"raw": {"C1": 13, "C2": 12, "C3": 15, "C4": 9, "C5": 8}, "code": "CIT", "name": "Máy tính và công nghệ thông tin", "score": 0.8661, "normalized": {"C1": 0.4642857142857143, "C2": 1, "C3": 1, "C4": 1, "C5": 1}, "description": "Nhóm ngành Máy tính và Công nghệ thông tin bao gồm các ngành học liên quan đến lĩnh vực máy tính, phần mềm, mạng và công nghệ thông tin. Đây là những ngành học nhằm chuẩn bị và phát triển kiến thức và kỹ năng liên quan đến việc thiết kế, phát triển và quản lý các hệ thống, ứng dụng công nghệ thông tin."}, {"raw": {"C1": 28, "C2": 3, "C3": 11, "C4": 3, "C5": 0}, "code": "MAT", "name": "Toán và thống kê", "score": 0.5217, "normalized": {"C1": 1, "C2": 0.25, "C3": 0.7333333333333333, "C4": 0.3333333333333333, "C5": 0}, "description": "Nhóm ngành Toán và Thống kê bao gồm các ngành học liên quan đến lý thuyết và ứng dụng của toán học và thống kê. Đây là những ngành học nhằm chuẩn bị và phát triển kiến thức và kỹ năng trong lĩnh vực tính toán, mô hình hóa và phân tích dữ liệu."}, {"raw": {"C1": 0, "C2": 4, "C3": 0, "C4": 6, "C5": 4}, "code": "BUS", "name": "Kinh doanh và quản lý", "score": 0.25, "normalized": {"C1": 0, "C2": 0.3333333333333333, "C3": 0, "C4": 0.6666666666666666, "C5": 0.5}, "description": "Nhóm ngành Kinh doanh và quản lý bao gồm các ngành học liên quan đến quản lý tổ chức và hoạt động kinh doanh. Đây là những ngành học nhằm chuẩn bị và phát triển các kỹ năng quản lý, lãnh đạo và kinh doanh trong các tổ chức và doanh nghiệp."}, {"raw": {"C1": 0, "C2": 4, "C3": 0, "C4": 2, "C5": 2}, "code": "TEC", "name": "Công nghệ kỹ thuật", "score": 0.1583, "normalized": {"C1": 0, "C2": 0.3333333333333333, "C3": 0, "C4": 0.2222222222222222, "C5": 0.25}, "description": "Nhóm ngành Công nghệ kỹ thuật bao gồm các ngành học liên quan đến việc áp dụng kiến thức kỹ thuật và kỹ năng thực hành để thiết kế, xây dựng, vận hành và bảo trì các hệ thống công nghiệp và cơ sở hạ tầng. Đây là những ngành học nhằm chuẩn bị và phát triển kiến thức và kỹ năng trong lĩnh vực kỹ thuật và công nghệ."}, {"raw": {"C1": 0, "C2": 4, "C3": 2, "C4": 0, "C5": 0}, "code": "ENG", "name": "Kỹ thuật", "score": 0.1267, "normalized": {"C1": 0, "C2": 0.3333333333333333, "C3": 0.13333333333333333, "C4": 0, "C5": 0}, "description": "Nhóm ngành Kỹ thuật bao gồm các ngành học tập trung vào việc áp dụng kiến thức và kỹ năng kỹ thuật để giải quyết các vấn đề trong các lĩnh vực công nghiệp, xây dựng, công trình, công nghệ và hệ thống."}, {"raw": {"C1": 0, "C2": 4, "C3": 0, "C4": 0, "C5": 1}, "code": "HUM", "name": "Nhân văn", "score": 0.1125, "normalized": {"C1": 0, "C2": 0.3333333333333333, "C3": 0, "C4": 0, "C5": 0.125}, "description": "Nhóm ngành Khoa học Nhân văn bao gồm các ngành học liên quan đến lĩnh vực xã hội, văn hóa, lịch sử và con người. Đây là những ngành học nhằm khám phá và hiểu sâu về các khía cạnh nhân văn của xã hội và cuộc sống."}, {"raw": {"C1": 2, "C2": 0, "C3": 2, "C4": 4, "C5": 0}, "code": "SCI", "name": "Khoa học tự nhiên", "score": 0.1112, "normalized": {"C1": 0.07142857142857142, "C2": 0, "C3": 0.13333333333333333, "C4": 0.4444444444444444, "C5": 0}, "description": "Nhóm ngành khoa học tự nhiên bao gồm các ngành học liên quan đến các lĩnh vực khoa học cơ bản như vật lý, hóa học, toán học, thiên văn học và các ngành khoa học tự nhiên khác. Nhóm ngành này tập trung vào nghiên cứu và hiểu về các quy luật tự nhiên, các quá trình và hiện tượng trong vũ trụ và tự nhiên xung quanh chúng ta."}, {"raw": {"C1": 0, "C2": 0, "C3": 4, "C4": 0, "C5": 4}, "code": "ART", "name": "Nghệ thuật", "score": 0.1033, "normalized": {"C1": 0, "C2": 0, "C3": 0.26666666666666666, "C4": 0, "C5": 0.5}, "description": "Nhóm ngành năng khiếu, nghệ thuật bao gồm các ngành học liên quan đến sự phát triển và khai thác các năng khiếu và tài năng trong lĩnh vực nghệ thuật. Đây là những ngành học nhằm chuẩn bị và phát triển các kỹ năng nghệ thuật và tạo điều kiện cho sinh viên thể hiện và phát triển sự sáng tạo của mình."}, {"raw": {"C1": 0, "C2": 2, "C3": 0, "C4": 0, "C5": 4}, "code": "JOU", "name": "Báo chí và thông tin", "score": 0.1, "normalized": {"C1": 0, "C2": 0.16666666666666666, "C3": 0, "C4": 0, "C5": 0.5}, "description": "Nhóm ngành báo chí, thông tin và truyền thông bao gồm các ngành học liên quan đến thu thập, xử lý và truyền đạt thông tin đến công chúng. Đây là những ngành học nhằm chuẩn bị và phát triển các kỹ năng liên quan đến việc làm trong lĩnh vực truyền thông và truyền thông đại chúng."}, {"raw": {"C1": 0, "C2": 0, "C3": 0, "C4": 4, "C5": 0}, "code": "LAW", "name": "Pháp luật", "score": 0.0667, "normalized": {"C1": 0, "C2": 0, "C3": 0, "C4": 0.4444444444444444, "C5": 0}, "description": "Nhóm ngành Pháp luật bao gồm các ngành học liên quan đến hệ thống pháp luật, luật pháp và quyền lợi trong xã hội. Đây là những ngành học nhằm chuẩn bị và phát triển các kiến thức và kỹ năng liên quan đến lĩnh vực pháp luật và hệ thống công lý."}, {"raw": {"C1": 0, "C2": 2, "C3": 0, "C4": 0, "C5": 0}, "code": "MAN", "name": "Sản xuất và chế biến", "score": 0.05, "normalized": {"C1": 0, "C2": 0.16666666666666666, "C3": 0, "C4": 0, "C5": 0}, "description": "Nhóm ngành sản xuất, chế biến bao gồm các ngành học liên quan đến quá trình chế biến, sản xuất và quản lý trong lĩnh vực công nghiệp và sản xuất hàng hóa. Đây là những ngành học đào tạo kiến thức và kỹ năng liên quan đến quy trình sản xuất, quản lý sản xuất, chế biến vật liệu và quản lý chất lượng."}, {"raw": {"C1": 0, "C2": 0, "C3": 0, "C4": 2, "C5": 0}, "code": "LIF", "name": "Khoa học sự sống", "score": 0.0333, "normalized": {"C1": 0, "C2": 0, "C3": 0, "C4": 0.2222222222222222, "C5": 0}, "description": "Nhóm ngành khoa học sự sống bao gồm các ngành học liên quan đến lĩnh vực sinh học, y học và nghiên cứu về sự sống. Đây là những ngành học nhằm chuẩn bị và phát triển kiến thức và kỹ năng liên quan đến các quá trình sinh học, cấu trúc và chức năng của hệ thống sống."}, {"raw": {"C1": 0, "C2": 0, "C3": 0, "C4": 1, "C5": 0}, "code": "ENV", "name": "Môi trường và bảo vệ môi trường", "score": 0.0167, "normalized": {"C1": 0, "C2": 0, "C3": 0, "C4": 0.1111111111111111, "C5": 0}, "description": "Nhóm ngành Môi trường và bảo vệ môi trường bao gồm các ngành học liên quan đến nghiên cứu, quản lý và bảo vệ tài nguyên tự nhiên và môi trường. Đây là những ngành học đào tạo kiến thức và kỹ năng liên quan đến bảo vệ và tái tạo môi trường, quản lý chất thải, nghiên cứu biến đổi khí hậu và phát triển bền vững."}], "sawScores": {"ART": 0.10333333333333333, "BUS": 0.25, "CIT": 0.8660714285714286, "ENG": 0.12666666666666665, "ENV": 0.016666666666666666, "HUM": 0.11249999999999999, "JOU": 0.1, "LAW": 0.06666666666666667, "LIF": 0.03333333333333333, "MAN": 0.049999999999999996, "MAT": 0.5216666666666667, "SCI": 0.11119047619047619, "TEC": 0.15833333333333333}, "totalAnswered": 30, "decisionMatrix": {"ART": {"C1": 0, "C2": 0, "C3": 4, "C4": 0, "C5": 4}, "BUS": {"C1": 0, "C2": 4, "C3": 0, "C4": 6, "C5": 4}, "CIT": {"C1": 13, "C2": 12, "C3": 15, "C4": 9, "C5": 8}, "ENG": {"C1": 0, "C2": 4, "C3": 2, "C4": 0, "C5": 0}, "ENV": {"C1": 0, "C2": 0, "C3": 0, "C4": 1, "C5": 0}, "HUM": {"C1": 0, "C2": 4, "C3": 0, "C4": 0, "C5": 1}, "JOU": {"C1": 0, "C2": 2, "C3": 0, "C4": 0, "C5": 4}, "LAW": {"C1": 0, "C2": 0, "C3": 0, "C4": 