INSERT INTO public."Submissions" VALUES (15, 7, 'CIT', 'Máy tính và công nghệ thông tin', NULL, NULL, 0.6833, '{"weights": {"C1": 0.25, "C2": 0.3, "C3": 0.2, "C4": 0.15, "C5": 0.1}, "criteria": [{"key": "C1", "label": "Academic Strength", "description": "Đánh giá môn học, tư duy học tập, khả năng học thuật"}, {"key": "C2", "label": "Interest", "description": "Điều bạn thích, hứng thú tự nhiên khi không bị áp lực"}, {"key": "C3", "label": "Skill", "description": "Bạn làm được gì tốt, thiên về thao tác – thực hành – kỹ thuật"}, {"key": "C4", "label": "Work Environment", "description": "Bạn phù hợp làm việc ở đâu – trong bối cảnh nào"}, {"key": "C5", "label": "Social Value", "description": "Bạn muốn đóng góp điều gì cho xã hội"}], "allScores": [{"raw": {"C1": 11, "C2": 6, "C3": 7, "C4": 5, "C5": 0}, "code": "CIT", "name": "Máy tính và công nghệ thông tin", "score": 0.6833, "normalized": {"C1": 0.4583333333333333, "C2": 1, "C3": 0.875, "C4": 0.625, "C5": 0}, "description": "Nhóm ngành Máy tính và Công nghệ thông tin bao gồm các ngành học liên quan đến lĩnh vực máy tính, phần mềm, mạng và công nghệ thông tin. Đây là những ngành học nhằm chuẩn bị và phát triển kiến thức và kỹ năng liên quan đến việc thiết kế, phát triển và quản lý các hệ thống, ứng dụng công nghệ thông tin."}, {"raw": {"C1": 24, "C2": 3, "C3": 3, "C4": 3, "C5": 0}, "code": "MAT", "name": "Toán và thống kê", "score": 0.5313, "normalized": {"C1": 1, "C2": 0.5, "C3": 0.375, "C4": 0.375, "C5": 0}, "description": "Nhóm ngành Toán và Thống kê bao gồm các ngành học liên quan đến lý thuyết và ứng dụng của toán học và thống kê. Đây là những ngành học nhằm chuẩn bị và phát triển kiến thức và kỹ năng trong lĩnh vực tính toán, mô hình hóa và phân tích dữ liệu."}, {"raw": {"C1": 0, "C2": 4, "C3": 4, "C4": 0, "C5": 0}, "code": "ART", "name": "Nghệ thuật", "score": 0.3, "normalized": {"C1": 0, "C2": 0.6666666666666666, "C3": 0.5, "C4": 0, "C5": 0}, "description": "Nhóm ngành năng khiếu, nghệ thuật bao gồm các ngành học liên quan đến sự phát triển và khai thác các năng khiếu và tài năng trong lĩnh vực nghệ thuật. Đây là những ngành học nhằm chuẩn bị và phát triển các kỹ năng nghệ thuật và tạo điều kiện cho sinh viên thể hiện và phát triển sự sáng tạo của mình."}, {"raw": {"C1": 2, "C2": 0, "C3": 1, "C4": 8, "C5": 8}, "code": "SCI", "name": "Khoa học tự nhiên", "score": 0.2958, "normalized": {"C1": 0.08333333333333333, "C2": 0, "C3": 0.125, "C4": 1, "C5": 1}, "description": "Nhóm ngành khoa học tự nhiên bao gồm các ngành học liên quan đến các lĩnh vực khoa học cơ bản như vật lý, hóa học, toán học, thiên văn học và các ngành khoa học tự nhiên khác. Nhóm ngành này tập trung vào nghiên cứu và hiểu về các quy luật tự nhiên, các quá trình và hiện tượng trong vũ trụ và tự nhiên xung quanh chúng ta."}, {"raw": {"C1": 4, "C2": 4, "C3": 1, "C4": 0, "C5": 0}, "code": "TOU", "name": "Du lịch, khách sạn, thể thao và dịch vụ cá nhân", "score": 0.2667, "normalized": {"C1": 0.16666666666666666, "C2": 0.6666666666666666, "C3": 0.125, "C4": 0, "C5": 0}, "description": "Nhóm ngành Du lịch, khách sạn, thể thao và dịch vụ cá nhân bao gồm các ngành học liên quan đến quản lý, phát triển và cung cấp các dịch vụ liên quan đến du lịch, khách sạn, thể thao và các dịch vụ cá nhân khác. Đây là những ngành học đào tạo kiến thức và kỹ năng liên quan đến quản lý, truyền thông, sáng tạo và tạo trải nghiệm cho khách hàng."}, {"raw": {"C1": 0, "C2": 2, "C3": 4, "C4": 0, "C5": 4}, "code": "JOU", "name": "Báo chí và thông tin", "score": 0.25, "normalized": {"C1": 0, "C2": 0.3333333333333333, "C3": 0.5, "C4": 0, "C5": 0.5}, "description": "Nhóm ngành báo chí, thông tin và truyền thông bao gồm các ngành học liên quan đến thu thập, xử lý và truyền đạt thông tin đến công chúng. Đây là những ngành học nhằm chuẩn bị và phát triển các kỹ năng liên quan đến việc làm trong lĩnh vực truyền thông và truyền thông đại chúng."}, {"raw": {"C1": 0, "C2": 4, "C3": 0, "C4": 0, "C5": 4}, "code": "SOC", "name": "Khoa học xã hội và hành vi", "score": 0.25, "normalized": {"C1": 0, "C2": 0.6666666666666666, "C3": 0, "C4": 0, "C5": 0.5}, "description": "Đây là nhóm ngành bao gồm các ngành học liên quan đến nghiên cứu và hiểu biết về xã hội, hành vi con người và các quá trình tâm lý. Đây là những ngành học nhằm khám phá và giải thích các khía cạnh xã hội, tâm lý và hành vi của con người."}, {"raw": {"C1": 0, "C2": 4, "C3": 1, "C4": 0, "C5": 0}, "code": "HUM", "name": "Nhân văn", "score": 0.225, "normalized": {"C1": 0, "C2": 0.6666666666666666, "C3": 0.125, "C4": 0, "C5": 0}, "description": "Nhóm ngành Khoa học Nhân văn bao gồm các ngành học liên quan đến lĩnh vực xã hội, văn hóa, lịch sử và con người. Đây là những ngành học nhằm khám phá và hiểu sâu về các khía cạnh nhân văn của xã hội và cuộc sống."}, {"raw": {"C1": 0, "C2": 0, "C3": 8, "C4": 0, "C5": 0}, "code": "EDU", "name": "Khoa học giáo dục và đào tạo giáo viên", "score": 0.2, "normalized": {"C1": 0, "C2": 0, "C3": 1, "C4": 0, "C5": 0}, "description": "Nhóm ngành Khoa học Giáo dục và Đào tạo giáo viên sư phạm bao gồm các ngành học liên quan đến lĩnh vực giáo dục và đào tạo giáo viên. Đây là những ngành học đào tạo giáo viên chất lượng, có kiến thức sâu về phương pháp dạy và quản lý lớp học."}, {"raw": {"C1": 0, "C2": 2, "C3": 0, "C4": 4, "C5": 0}, "code": "LAW", "name": "Pháp luật", "score": 0.175, "normalized": {"C1": 0, "C2": 0.3333333333333333, "C3": 0, "C4": 0.5, "C5": 0}, "description": "Nhóm ngành Pháp luật bao gồm các ngành học liên quan đến hệ thống pháp luật, luật pháp và quyền lợi trong xã hội. Đây là những ngành học nhằm chuẩn bị và phát triển các kiến thức và kỹ năng liên quan đến lĩnh vực pháp luật và hệ thống công lý."}, {"raw": {"C1": 0, "C2": 0, "C3": 0, "C4": 6, "C5": 4}, "code": "BUS", "name": "Kinh doanh và quản lý", "score": 0.1625, "normalized": {"C1": 0, "C2": 0, "C3": 0, "C4": 0.75, "C5": 0.5}, "description": "Nhóm ngành Kinh doanh và quản lý bao gồm các ngành học liên quan đến quản lý tổ chức và hoạt động kinh doanh. Đây là những ngành học nhằm chuẩn bị và phát triển các kỹ năng quản lý, lãnh đạo và kinh doanh trong các tổ chức và doanh nghiệp."}, {"raw": {"C1": 0, "C2": 2, "C3": 0, "C4": 1, "C5": 1}, "code": "TEC", "name": "Công nghệ kỹ thuật", "score": 0.1313, "normalized": {"C1": 0, "C2": 0.3333333333333333, "C3": 0, "C4": 0.125, "C5": 0.125}, "description": "Nhóm ngành Công nghệ kỹ thuật bao gồm các ngành học liên quan đến việc áp dụng kiến thức kỹ thuật và kỹ năng thực hành để thiết kế, xây dựng, vận hành và bảo trì các hệ thống công nghiệp và cơ sở hạ tầng. Đây là những ngành học nhằm chuẩn bị và phát triển kiến thức và kỹ năng trong lĩnh vực kỹ thuật và công nghệ."}, {"raw": {"C1": 0, "C2": 0, "C3": 0, "C4": 4, "C5": 2}, "code": "LIF", "name": "Khoa học sự sống", "score": 0.1, "normalized": {"C1": 0, "C2": 0, "C3": 0, "C4": 0.5, "C5": 0.25}, "description": "Nhóm ngành khoa học sự sống bao gồm các ngành học liên quan đến lĩnh vực sinh học, y học và nghiên cứu về sự sống. Đây là những ngành học nhằm chuẩn bị và phát triển kiến thức và kỹ năng liên quan đến các quá trình sinh học, cấu trúc và chức năng của hệ thống sống."}, {"raw": {"C1": 0, "C2": 2, "C3": 0, "C4": 0, "C5": 0}, "code": "WEL", "name": "Dịch vụ xã hội", "score": 0.1, "normalized": {"C1": 0, "C2": 0.3333333333333333, "C3": 0, "C4": 0, "C5": 0}, "description": "Nhóm ngành Dịch vụ xã hội bao gồm các ngành học liên quan đến cung cấp và quản lý các dịch vụ hỗ trợ xã hội cho các cá nhân, gia đình và cộng đồng. Đây là những ngành đào tạo kiến thức và kỹ năng liên quan đến công tác xã hội, tư vấn, giáo dục và quản lý dịch vụ xã hội."}, {"raw": {"C1": 0, "C2": 0, "C3": 2, "C4": 0, "C5": 0}, "code": "ENG", "name": "Kỹ thuật", "score": 0.05, "normalized": {"C1": 0, "C2": 0, "C3": 0.25, "C4": 0, "C5": 0}, "description": "Nhóm ngành Kỹ thuật bao gồm các ngành học tập trung vào việc áp dụng kiến thức và kỹ năng kỹ thuật để giải quyết các vấn đề trong các lĩnh vực công nghiệp, xây dựng, công trình, công nghệ và hệ thống."}, {"raw