INSERT INTO public."Submissions" VALUES (45, 11, 'EDU', 'Khoa học giáo dục và đào tạo giáo viên', NULL, NULL, 0.55, '{"weights": {"C1": 0.25, "C2": 0.3, "C3": 0.2, "C4": 0.15, "C5": 0.1, "CCIT1": 0.1111111111111111, "CCIT2": 0.1111111111111111, "CCIT3": 0.1111111111111111, "CCIT4": 0.1111111111111111}, "criteria": [{"key": "C1", "label": "Academic Strength", "weight": null, "description": "Đánh giá môn học, tư duy học tập, khả năng học thuật"}, {"key": "C2", "label": "Interest", "weight": null, "description": "Điều bạn thích, hứng thú tự nhiên khi không bị áp lực"}, {"key": "C3", "label": "Skill", "weight": null, "description": "Bạn làm được gì tốt, thiên về thao tác – thực hành – kỹ thuật"}, {"key": "C4", "label": "Work Environment", "weight": null, "description": "Bạn phù hợp làm việc ở đâu – trong bối cảnh nào"}, {"key": "C5", "label": "Social Value", "weight": null, "description": "Bạn muốn đóng góp điều gì cho xã hội"}, {"key": "CCIT1", "label": "Academic Ability", "weight": null, "description": "Năng lực học thuật và tư duy logic, toán học – nền tảng cho lập trình và thuật toán"}, {"key": "CCIT2", "label": "Technical Interest & Skills", "weight": null, "description": "Hứng thú và kỹ năng kỹ thuật chuyên biệt: lập trình, mạng, bảo mật, AI, dữ liệu, thiết kế"}, {"key": "CCIT3", "label": "Personal Traits", "weight": null, "description": "Tính cách và phong cách làm việc: sáng tạo, có tổ chức, giao tiếp, teamwork"}, {"key": "CCIT4", "label": "Career Orientation", "weight": null, "description": "Định hướng nghề nghiệp và mục tiêu phát triển trong lĩnh vực CNTT"}], "allScores": [{"raw": {"C1": 7, "C2": 0, "C3": 8, "C4": 0, "C5": 8, "CCIT1": 0, "CCIT2": 0, "CCIT3": 0, "CCIT4": 0}, "code": "EDU", "name": "Khoa học giáo dục và đào tạo giáo viên", "score": 0.55, "normalized": {"C1": 1, "C2": 0, "C3": 1, "C4": 0, "C5": 1, "CCIT1": 0, "CCIT2": 0, "CCIT3": 0, "CCIT4": 0}, "description": "Nhóm ngành Khoa học Giáo dục và Đào tạo giáo viên sư phạm bao gồm các ngành học liên quan đến lĩnh vực giáo dục và đào tạo giáo viên. Đây là những ngành học đào tạo giáo viên chất lượng, có kiến thức sâu về phương pháp dạy và quản lý lớp học."}, {"raw": {"C1": 2, "C2": 9, "C3": 4, "C4": 3, "C5": 0, "CCIT1": 0, "CCIT2": 0, "CCIT3": 0, "CCIT4": 0}, "code": "JOU", "name": "Báo chí và thông tin", "score": 0.5089, "normalized": {"C1": 0.2857142857142857, "C2": 1, "C3": 0.5, "C4": 0.25, "C5": 0, "CCIT1": 0, "CCIT2": 0, "CCIT3": 0, "CCIT4": 0}, "description": "Nhóm ngành báo chí, thông tin và truyền thông bao gồm các ngành học liên quan đến thu thập, xử lý và truyền đạt thông tin đến công chúng. Đây là những ngành học nhằm chuẩn bị và phát triển các kỹ năng liên quan đến việc làm trong lĩnh vực truyền thông và truyền thông đại chúng."}, {"raw": {"C1": 6, "C2": 6, "C3": 1, "C4": 1, "C5": 1, "CCIT1": 0, "CCIT2": 0, "CCIT3": 0, "CCIT4": 0}, "code": "HUM", "name": "Nhân văn", "score": 0.4643, "normalized": {"C1": 0.8571428571428571, "C2": 0.6666666666666666, "C3": 0.125, "C4": 0.08333333333333333, "C5": 0.125, "CCIT1": 0, "CCIT2": 0, "CCIT3": 0, "CCIT4": 0}, "description": "Nhóm ngành Khoa học Nhân văn bao gồm các ngành học liên quan đến lĩnh vực xã hội, văn hóa, lịch sử và con người. Đây là những ngành học nhằm khám phá và hiểu sâu về các khía cạnh nhân văn của xã hội và cuộc sống."}, {"raw": {"C1": 4, "C2": 4, "C3": 0, "C4": 12, "C5": 0, "CCIT1": 0, "CCIT2": 0, "CCIT3": 0, "CCIT4": 0}, "code": "BUS", "name": "Kinh doanh và quản lý", "score": 0.4262, "normalized": {"C1": 0.5714285714285714, "C2": 0.4444444444444444, "C3": 0, "C4": 1, "C5": 0, "CCIT1": 0, "CCIT2": 0, "CCIT3": 0, "CCIT4": 0}, "description": "Nhóm ngành Kinh doanh và quản lý bao gồm các ngành học liên quan đến quản lý tổ chức và hoạt động kinh doanh. Đây là những ngành học nhằm chuẩn bị và phát triển các kỹ năng quản lý, lãnh đạo và kinh doanh trong các tổ chức và doanh nghiệp."}, {"raw": {"C1": 4, "C2": 2, "C3": 2, "C4": 8, "C5": 4, "CCIT1": 0, "CCIT2": 0, "CCIT3": 0, "CCIT4": 0}, "code": "ART", "name": "Nghệ thuật", "score": 0.4095, "normalized": {"C1": 0.5714285714285714, "C2": 0.2222222222222222, "C3": 0.25, "C4": 0.6666666666666666, "C5": 0.5, "CCIT1": 0, "CCIT2": 0, "CCIT3": 0, "CCIT4": 0}, "description": "Nhóm ngành năng khiếu, nghệ thuật bao gồm các ngành học liên quan đến sự phát triển và khai thác các năng khiếu và tài năng trong lĩnh vực nghệ thuật. Đây là những ngành học nhằm chuẩn bị và phát triển các kỹ năng nghệ thuật và tạo điều kiện cho sinh viên thể hiện và phát triển sự sáng tạo của mình."}, {"raw": {"C1": 1, "C2": 8, "C3": 0, "C4": 0, "C5": 4, "CCIT1": 0, "CCIT2": 0, "CCIT3": 0, "CCIT4": 0}, "code": "SOC", "name": "Khoa học xã hội và hành vi", "score": 0.3524, "normalized": {"C1": 0.14285714285714285, "C2": 0.8888888888888888, "C3": 0, "C4": 0, "C5": 0.5, "CCIT1": 0, "CCIT2": 0, "CCIT3": 0, "CCIT4": 0}, "description": "Đây là nhóm ngành bao gồm các ngành học liên quan đến nghiên cứu và hiểu biết về xã hội, hành vi con người và các quá trình tâm lý. Đây là những ngành học nhằm khám phá và giải thích các khía cạnh xã hội, tâm lý và hành vi của con người."}, {"raw": {"C1": 4, "C2": 4, "C3": 0, "C4": 0, "C5": 4, "CCIT1": 0, "CCIT2": 0, "CCIT3": 0, "CCIT4": 0}, "code": "LAW", "name": "Pháp luật", "score": 0.3262, "normalized": {"C1": 0.5714285714285714, "C2": 0.4444444444444444, "C3": 0, "C4": 0, "C5": 0.5, "CCIT1": 0, "CCIT2": 0, "CCIT3": 0, "CCIT4": 0}, "description": "Nhóm ngành Pháp luật bao gồm các ngành học liên quan đến hệ thống pháp luật, luật pháp và quyền lợi trong xã hội. Đây là những ngành học nhằm chuẩn bị và phát triển các kiến thức và kỹ năng liên quan đến lĩnh vực pháp luật và hệ thống công lý."}, {"raw": {"C1": 4, "C2": 4, "C3": 0, "C4": 0, "C5": 0, "CCIT1": 0, "CCIT2": 0, "CCIT3": 0, "CCIT4": 0}, "code": "WEL", "name": "Dịch vụ xã hội", "score": 0.2762, "normalized": {"C1": 0.5714285714285714, "C2": 0.4444444444444444, "C3": 0, "C4": 0, "C5": 0, "CCIT1": 0, "CCIT2": 0, "CCIT3": 0, "CCIT4": 0}, "description": "Nhóm ngành Dịch