INSERT INTO public."Submissions" VALUES (49, 15, 'BUS', 'Kinh doanh và quản lý', NULL, NULL, 0.5867, '{"weights": {"C1": 0.25, "C2": 0.3, "C3": 0.2, "C4": 0.15, "C5": 0.1, "CCIT1": 0.1111111111111111, "CCIT2": 0.1111111111111111, "CCIT3": 0.1111111111111111, "CCIT4": 0.1111111111111111}, "criteria": [{"key": "C1", "label": "Academic Strength", "weight": null, "description": "Đánh giá môn học, tư duy học tập, khả năng học thuật"}, {"key": "C2", "label": "Interest", "weight": null, "description": "Điều bạn thích, hứng thú tự nhiên khi không bị áp lực"}, {"key": "C3", "label": "Skill", "weight": null, "description": "Bạn làm được gì tốt, thiên về thao tác – thực hành – kỹ thuật"}, {"key": "C4", "label": "Work Environment", "weight": null, "description": "Bạn phù hợp làm việc ở đâu – trong bối cảnh nào"}, {"key": "C5", "label": "Social Value", "weight": null, "description": "Bạn muốn đóng góp điều gì cho xã hội"}, {"key": "CCIT1", "label": "Academic Ability", "weight": null, "description": "Năng lực học thuật và tư duy logic, toán học – nền tảng cho lập trình và thuật toán"}, {"key": "CCIT2", "label": "Technical Interest & Skills", "weight": null, "description": "Hứng thú và kỹ năng kỹ thuật chuyên biệt: lập trình, mạng, bảo mật, AI, dữ liệu, thiết kế"}, {"key": "CCIT3", "label": "Personal Traits", "weight": null, "description": "Tính cách và phong cách làm việc: sáng tạo, có tổ chức, giao tiếp, teamwork"}, {"key": "CCIT4", "label": "Career Orientation", "weight": null, "description": "Định hướng nghề nghiệp và mục tiêu phát triển trong lĩnh vực CNTT"}], "allScores": [{"raw": {"C1": 4, "C2": 4, "C3": 4, "C4": 14, "C5": 4, "CCIT1": 0, "CCIT2": 0, "CCIT3": 0, "CCIT4": 0}, "code": "BUS", "name": "Kinh doanh và quản lý", "score": 0.5867, "normalized": {"C1": 0.6666666666666666, "C2": 0.4, "C3": 0.5, "C4": 1, "C5": 0.5, "CCIT1": 0, "CCIT2": 0, "CCIT3": 0, "CCIT4": 0}, "description": "Nhóm ngành Kinh doanh và quản lý bao gồm các ngành học liên quan đến quản lý tổ chức và hoạt động kinh doanh. Đây là những ngành học nhằm chuẩn bị và phát triển các kỹ năng quản lý, lãnh đạo và kinh doanh trong các tổ chức và doanh nghiệp."}, {"raw": {"C1": 6, "C2": 0, "C3": 8, "C4": 2, "C5": 6, "CCIT1": 0, "CCIT2": 0, "CCIT3": 0, "CCIT4": 0}, "code": "EDU", "name": "Khoa học giáo dục và đào tạo giáo viên", "score": 0.5464, "normalized": {"C1": 1, "C2": 0, "C3": 1, "C4": 0.14285714285714285, "C5": 0.75, "CCIT1": 0, "CCIT2": 0, "CCIT3": 0, "CCIT4": 0}, "description": "Nhóm ngành Khoa học Giáo dục và Đào tạo giáo viên sư phạm bao gồm các ngành học liên quan đến lĩnh vực giáo dục và đào tạo giáo viên. Đây là những ngành học đào tạo giáo viên chất lượng, có kiến thức sâu về phương pháp dạy và quản lý lớp học."}, {"raw": {"C1": 2, "C2": 10, "C3": 0, "C4": 4, "C5": 4, "CCIT1": 0, "CCIT2": 0, "CCIT3": 0, "CCIT4": 0}, "code": "CIT", "name": "Máy tính và công nghệ thông tin", "score": 0.4762, "normalized": {"C1": 0.3333333333333333, "C2": 1, "C3": 0, "C4": 0.2857142857142857, "C5": 0.5, "CCIT1": 0, "CCIT2": 0, "CCIT3": 0, "CCIT4": 0}, "description": "Nhóm ngành Máy tính và Công nghệ thông tin bao gồm các ngành học liên quan đến lĩnh vực máy tính, phần mềm, mạng và công nghệ thông tin. Đây là những ngành học nhằm chuẩn bị và phát triển kiến thức và kỹ năng liên quan đến việc thiết kế, phát triển và quản lý các hệ thống, ứng dụng công nghệ thông tin."}, {"raw": {"C1": 6, "C2": 2, "C3": 1, "C4": 0, "C5": 0, "CCIT1": 0, "CCIT2": 0, "CCIT3": 0, "CCIT4": 0}, "code": "HUM", "name": "Nhân văn", "score": 0.335, "normalized": {"C1": 1, "C2": 0.2, "C3": 0.125, "C4": 0, "C5": 0, "CCIT1": 0, "CCIT2": 0, "CCIT3": 0, "CCIT4": 0}, "description": "Nhóm ngành Khoa học Nhân văn bao gồm các ngành học liên quan đến lĩnh vực xã hội, văn hóa, lịch sử và con người. Đây là những ngành học nhằm khám phá và hiểu sâu về các khía cạnh nhân văn của xã hội và cuộc sống."}, {"raw": {"C1": 4, "C2": 4, "C3": 0, "C4": 0, "C5": 2, "CCIT1": 0, "CCIT2": 0, "CCIT3": 0, "CCIT4": 0}, "code": "TEC", "name": "Công nghệ kỹ thuật", "score": 0.3117, "normalized": {"C1": 0.6666666666666666, "C2": 0.4, "C3": 0, "C4": 0, "C5": 0.25, "CCIT1": 0, "CCIT2": 0, "CCIT3": 0, "CCIT4": 0}, "description": "Nhóm ngành Công nghệ kỹ thuật bao gồm các ngành học liên quan đến việc áp dụng kiến thức kỹ thuật và kỹ năng thực hành để thiết kế, xây dựng, vận hành và bảo trì các hệ thống công nghiệp và cơ sở hạ tầng. Đây là những ngành học nhằm chuẩn bị và phát triển kiến thức và kỹ năng trong lĩnh vực kỹ thuật và công nghệ."}, {"raw": {"C1": 4, "C2": 4, "C3": 0, "C4": 0, "C5": 0, "CCIT1": 0, "CCIT2": 0, "CCIT3": 0, "CCIT4": 0}, "code": "TOU", "name": "Du lịch, khách sạn, thể thao và dịch vụ cá nhân", "score": 0.2867, "normalized": {"C1": 0.6666666666666666, "C2": 0.4, "C3": 0, "C4": 0, "C5": 0, "CCIT1": 0, "CCIT2": 0, "CCIT3": 0, "CCIT4": 0}, "description": "Nhóm ngành Du lịch, khách sạn, thể thao và dịch vụ cá nhân bao gồm các ngành học liên quan đến quản lý, phát triển và cung cấp các dịch vụ liên quan đến du lịch, khách sạn, thể thao và các dịch vụ cá nhân khác. Đây là những ngành học đào tạo kiến thức và kỹ năng liên quan đến quản lý, truyền thông, sáng tạo và tạo trải nghiệm cho khách hàng."}, {"raw": {"C1": 0, "C2": 2, "C3": 6, "C4": 4, "C5": 0, "CCIT1": 0, "CCIT2": 0, "CCIT3": 0, "CCIT4": 0}, "code": "MAN", "name": "Sản xuất và chế biến", "score": 0.2529, "normalized": {"C1": 0, "C2": 0.2, "C3": 0.75, "C4": 0.2857142857142857, "C5": 0, "CCIT1": 0, "CCIT2": 0, "CCIT3": 0, "CCIT4": 0}, "description": "Nhóm ngành sản xuất, chế biến bao gồm các ngành học liên quan đến quá trình chế biến, sản xuất và quản lý trong lĩnh vực công nghiệp và sản xuất hàng hóa. Đây là những ngành học đào tạo kiến thức và kỹ năng liên quan đến quy trình sản xuất, quản lý sản xuất, chế biến vật liệu và quản lý chất lượng."}, {"raw": {"C1": 2, "C2": 4, "C3": 0, "C4": 0, "C5": 0, "CCIT1": 0, "CCIT2": 0, "CCIT3": 0, "CCIT4": 0}, "code": "ENG", "name": "Kỹ thuật", "score": 0.2033, "normalized": {"C1": 0.3333333333333333, "C2": 0.4, "C3": 0, "C4": 0, "C5": 0, "CCIT1": 0, "CCIT2": 0, "CCIT3": 0, "CCIT4": 0}, "description": "Nhóm ngành Kỹ thuật bao gồm các ngành học tập trung vào việc áp dụng kiến thức và kỹ năng kỹ thuật để giải quyết các vấn đề trong các lĩnh vực công nghiệp, xây dựng, công trình, công nghệ và hệ thống."}, {"raw": {"C1": 4, "C2": 0, "C3": 0, "C4": 0, "C5": 0, "CCIT1": 0, "CCIT2": 0, "CCIT3": 0, "CCIT4": 0}, "code": "MAT", "name": "Toán và thống kê", "score": 0.1667, "normalized": {"C1": 0.6666666666666666, "C2": 0, "C3": 0, "C4": 0, "C5": 0, "CCIT1": 0, "CCIT2": 0, "CCIT3": 0, "CCIT4": 0}, "description": "Nhóm ngành Toán và Thống kê bao gồm các ngành học liên quan đến lý thuyết và ứng dụng của toán học và thống kê. Đây là những ngành học nhằm chuẩn bị và phát triển kiến thức và kỹ năng trong lĩnh vực tính toán, mô hình hóa và phân tích dữ liệu."}, {"raw": {"C1": 4, "C2": 0, "C3": 0, "C4": 0, "C5": 0, "CCIT1": 0, "CCIT2": 0, "CCIT3": 0, "CCIT4": 0}, "code": "LAW", "name": "Pháp luật", "score": 0.1667, "normalized": {"C1": 0.6666666666666666, "C2": 0, "C3": 0, "C4": 0, "C5": 0, "CCIT1": 0, "CCIT2": 0, "CCIT3": 0, "CCIT4": 0}, "description": "Nhóm ngành Pháp luật bao gồm các ngành học liên quan đến hệ thống pháp luật, luật pháp và quyền lợi trong xã hội. Đây là những ngành học nhằm chuẩn bị và phát triển các kiến thức và kỹ năng liên quan đến lĩnh vực pháp luật và hệ thống công lý."}, {"raw": {"C1": 0, "C2": 0, "C3": 4, "C4": 1, "C5": 0, "CCIT1": 0, "CCIT2": 0, "CCIT3": 0, "CCIT4": 0}, "code": "TRA", "name": "Dịch vụ vận tải", "score": 0.1107, "normalized": {"C1": 0, "C2": 0, "C3": 0.5, "C4": 0.07142857142857142, "C5": 0, "CCIT1": 0, "CCIT2": 0, "CCIT3": 0, "CCIT4": 0}, "description": "Nhóm ngành Dịch vụ vận tải bao gồm các ngành học liên quan đến quản lý, điều hành và cung cấp các dịch vụ vận chuyển và giao thông. Đây là những ngành học đào tạo kiến thức và kỹ năng liên quan đến quản lý hệ thống vận tải, kỹ thuật phương tiện và các dịch vụ liên quan."}, {"raw": {"C