INSERT INTO public."Submissions" VALUES (53, 1, 'CIT', 'Máy tính và công nghệ thông tin', NULL, NULL, 0.8661, '{"weights": {"C1": 0.25, "C2": 0.3, "C3": 0.2, "C4": 0.15, "C5": 0.1, "CCIT1": 0.1111111111111111, "CCIT2": 0.1111111111111111, "CCIT3": 0.1111111111111111, "CCIT4": 0.1111111111111111}, "criteria": [{"key": "C1", "label": "Academic Strength", "weight": null, "description": "Đánh giá môn học, tư duy học tập, khả năng học thuật"}, {"key": "C2", "label": "Interest", "weight": null, "description": "Điều bạn thích, hứng thú tự nhiên khi không bị áp lực"}, {"key": "C3", "label": "Skill", "weight": null, "description": "Bạn làm được gì tốt, thiên về thao tác – thực hành – kỹ thuật"}, {"key": "C4", "label": "Work Environment", "weight": null, "description": "Bạn phù hợp làm việc ở đâu – trong bối cảnh nào"}, {"key": "C5", "label": "Social Value", "weight": null, "description": "Bạn muốn đóng góp điều gì cho xã hội"}, {"key": "CCIT1", "label": "Academic Ability", "weight": null, "description": "Năng lực học thuật và tư duy logic, toán học – nền tảng cho lập trình và thuật toán"}, {"key": "CCIT2", "label": "Technical Interest & Skills", "weight": null, "description": "Hứng thú và kỹ năng kỹ thuật chuyên biệt: lập trình, mạng, bảo mật, AI, dữ liệu, thiết kế"}, {"key": "CCIT3", "label": "Personal Traits", "weight": null, "description": "Tính cách và phong cách làm việc: sáng tạo, có tổ chức, giao tiếp, teamwork"}, {"key": "CCIT4", "label": "Career Orientation", "weight": null, "description": "Định hướng nghề nghiệp và mục tiêu phát triển trong lĩnh vực CNTT"}], "allScores": [{"raw": {"C1": 13, "C2": 12, "C3": 16, "C4": 9, "C5": 8, "CCIT1": 0, "CCIT2": 0, "CCIT3": 0, "CCIT4": 0}, "code": "CIT", "name": "Máy tính và công nghệ thông tin", "score": 0.8661, "normalized": {"C1": 0.4642857142857143, "C2": 1, "C3": 1, "C4": 1, "C5": 1, "CCIT1": 0, "CCIT2": 0, "CCIT3": 0, "CCIT4": 0}, "description": "Nhóm ngành Máy tính và Công nghệ thông tin bao gồm các ngành học liên quan đế