INSERT INTO public.criteria VALUES ('C1', 'Academic Strength', 'Đánh giá môn học, tư duy học tập, khả năng học thuật', 1, 1);
INSERT INTO public.criteria VALUES ('C2', 'Interest', 'Điều bạn thích, hứng thú tự nhiên khi không bị áp lực', 2, 1);
INSERT INTO public.criteria VALUES ('C3', 'Skill', 'Bạn làm được gì tốt, thiên về thao tác – thực hành – kỹ thuật', 3, 1);
INSERT INTO public.criteria VALUES ('C4', 'Work Environment', 'Bạn phù hợp làm việc ở đâu – trong bối cảnh nào', 4, 1);
INSERT INTO public.criteria VALUES ('C5', 'Social Value', 'Bạn muốn đóng góp điều gì cho xã hội', 5, 1);
INSERT INTO public.criteria VALUES ('CCIT1', 'Academic Ability', 'Năng lực học thuật và tư duy logic, toán học – nền tảng cho lập trình và thuật toán', 6, 2);
INSERT INTO public.criteria VALUES ('CCIT2', 'Technical Interest & Skills', 'Hứng thú và kỹ năng kỹ thuật chuyên biệt: lập trình, mạng, bảo mật, AI, dữ liệu, thiết kế', 7, 2);
INSERT INTO public.criteria VALUES ('CCIT3', 'Personal Traits', 'Tính cách và phong cách làm việc: sáng tạo, có tổ chức, giao tiếp, teamwork', 8, 2);
INSERT INTO public.criteria VALUES ('CCIT4', 'Career Orientation', 'Định hướng nghề nghiệp và mục tiêu phát triển trong lĩnh vực CNTT', 9, 2);
INSERT INTO public.questions VALUES (125, 'Câu 1: Khi gặp một bài toán hoặc một câu đố logic cực khó, phản xạ của bạn là:', '2026-04-01 15:29:52.027345+07', '2026-04-01 15:29:52.027345+07', 2, NULL, NULL, 'multiple_choice');
